        """Create a new user"""
        user_id = str(uuid.uuid4())
        user = User(
            id=user_id,
            username=user_data['username'],
            email=user_data['email'],
            password_hash=user_data['password_hash'],
            role=user_data['role'],
            native_language=user_data['native_language'],
            target_languages=user_data.get('target_languages', []),
            created_at=datetime.now()
        )
        self.users[user_id] = user
        return user

    def get_user(self, user_id: str) -> Optional[User]:
        """Retrieve user by ID"""
        return self.users.get(user_id)

    def get_user_by_email(self, email: str) -> Optional[User]:
        """Retrieve user by email"""
        for user in self.users.values():
            if user.email == email:
                return user
        return None

    def update_user(self, user_id: str, updates: Dict) -> Optional[User]:
        """Update user information"""
        if user_id in self.users:
            user = self.users[user_id]
            for key, value in updates.items():
                if hasattr(user, key):
                    setattr(user, key, value)
            return user
        return None

    # Session operations
    def create_session(self, session_data: Dict) -> ConversationSession:
        """Create a new conversation session"""
        session_id = str(uuid.uuid4())
        session = ConversationSession(
            id=session_id,
            learner_id=session_data['learner_id'],
            native_speaker_id=session_data['native_speaker_id'],
            language=session_data['language'],
            start_time=datetime.now()
        )
        self.sessions[session_id] = session
        return session

    def add_message_to_session(self, session_id: str, sender_id: str, message: str) -> bool:
        """Add a message to conversation session"""
        if session_id in self.sessions:
            self.sessions[session_id].chat_log.append({
                "sender": sender_id,
                "message": message,
                "timestamp": datetime.now()
            })
            return True
        return False

