from enum import Enum
from typing import List, Dict, Tuple, Optional, Any
import random
import math
import json
from dataclasses import dataclass, field
from abc import ABC, abstractmethod

# ============================================================================
# ENUMS AND CONSTANTS
# ============================================================================

class AgentRole(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SCOUT = "scout"
    SUPPORT = "support"

class AgentAbility(Enum):
    INCREASED_SPEED = "increased_speed"
    HEALING = "healing"
    SHIELDING = "shielding"
    STEALTH = "stealth"
    TELEPORT = "teleport"

class ObjectiveType(Enum):
    CAPTURE_FLAG = "capture_flag"
    DEFEND_BASE = "defend_base"
    ELIMINATE_ENEMIES = "eliminate_enemies"
    ESCORT = "escort"

class MessageType(Enum):
    ENEMY_LOCATION = "enemy_location"
    OBJECTIVE_STATUS = "objective_status"
    STRATEGIC_PLAN = "strategic_plan"
    REQUEST_HELP = "request_help"
    STATUS_UPDATE = "status_update"

# ============================================================================
# DATA CLASSES
# ============================================================================

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def move_toward(self, target: 'Position', speed: float) -> 'Position':
        dx = target.x - self.x
        dy = target.y - self.y
        distance = math.sqrt(dx**2 + dy**2)
        if distance == 0:
            return self
        return Position(
            self.x + (dx / distance) * speed,
            self.y + (dy / distance) * speed
        )

@dataclass
class AgentState:
    agent_id: str
    role: AgentRole
    position: Position
    health: int = 100
    abilities: List[AgentAbility] = field(default_factory=list)
    is_alive: bool = True
    has_flag: bool = False
    shield_active: bool = False

    def take_damage(self, damage: int) -> bool:
        if self.shield_active:
            damage = max(0, damage - 20)
        self.health -= damage
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
        return self.is_alive

    def heal(self, amount: int):
        if self.is_alive:
            self.health = min(100, self.health + amount)

    def activate_shield(self):
        if AgentAbility.SHIELDING in self.abilities:
            self.shield_active = True

    def deactivate_shield(self):
        self.shield_active = False

@dataclass
class Message:
    sender_id: str
    message_type: MessageType
    content: Dict[str, Any]
    timestamp: float = field(default_factory=lambda: time.time())

# ============================================================================
