# ============================================================================

class AIAgent(ABC):
    def __init__(self, agent_id: str, role: AgentRole, abilities: List[AgentAbility]):
        self.agent_id = agent_id
        self.role = role
        self.abilities = abilities
        self.state = AgentState(agent_id, role, Position(0, 0), abilities=abilities)
        self.inbox: List[Message] = []
        self.outbox: List[Message] = []

    @abstractmethod
    def decide_action(self, game_state: 'GameState') -> Dict[str, Any]:
        pass

    def send_message(self, message_type: MessageType, content: Dict[str, Any]):
        message = Message(self.agent_id, message_type, content)
        self.outbox.append(message)

    def receive_message(self, message: Message):
        self.inbox.append(message)

    def get_speed(self) -> float:
        speed = 1.0
        if AgentAbility.INCREASED_SPEED in self.abilities:
            speed *= 1.5
