from dataclasses import dataclass, field
from enum import Enum
from collections import deque


# ==================== ENUMS AND DATA CLASSES ====================

class AgentRole(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SCOUT = "scout"
    MEDIC = "medic"

class AgentAbility(Enum):
    SPEED_BOOST = "speed_boost"
    HEALING = "healing"
    SHIELDING = "shielding"
    STEALTH = "stealth"
    DAMAGE_BOOST = "damage_boost"

class ObjectiveType(Enum):
    CAPTURE_FLAG = "capture_flag"
    DEFEND_BASE = "defend_base"
    ELIMINATE_ENEMIES = "eliminate_enemies"

class MessageType(Enum):
    ENEMY_SPOTTED = "enemy_spotted"
    OBJECTIVE_STATUS = "objective_status"
    REQUEST_HELP = "request_help"
    STRATEGY_PLAN = "strategy_plan"
    POSITION_UPDATE = "position_update"


@dataclass
class Vector2D:
    x: float
    y: float

    def distance_to(self, other: 'Vector2D') -> float:
        return math.sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2)

    def move_toward(self, target: 'Vector2D', speed: float) -> 'Vector2D':
        dx = target.x - self.x
        dy = target.y - self.y
        dist = self.distance_to(target)
        if dist == 0:
            return self
        return Vector2D(
            self.x + (dx / dist) * min(speed, dist),
            self.y + (dy / dist) * min(speed, dist)
        )


@dataclass
class GameMessage:
    sender_id: int
    message_type: MessageType
    content: Dict[str, Any]
    timestamp: float = field(default_factory=lambda: random.random() * 1000)
    priority: int = 1  # 1=low, 2=medium, 3=high


