        responses = []
        while self.message_queue:
            msg = self.message_queue.popleft()
            response = self._process_message(msg)
            if response:
                responses.append(response)
        return responses

    def _process_message(self, message: GameMessage) -> Optional[GameMessage]:
        # Base implementation - to be overridden by specific agent types
        if message.message_type == MessageType.REQUEST_HELP:
