# solution.py
"""
LanguageSkillEnhancer - A comprehensive language learning application
that provides vocabulary, grammar, and comprehension exercises with
progress tracking and analytics.
"""

import json
import random
import datetime
from abc import ABC, abstractmethod
from typing import Dict, List, Tuple, Optional, Any
from dataclasses import dataclass, field
from enum import Enum


class Difficulty(Enum):
    """Difficulty levels for exercises."""
    BEGINNER = "beginner"
    INTERMEDIATE = "intermediate"
    ADVANCED = "advanced"


class Language(Enum):
    """Supported languages."""
    ENGLISH = "English"
    SPANISH = "Spanish"
    FRENCH = "French"
    GERMAN = "German"
    JAPANESE = "Japanese"


class ExerciseType(Enum):
    """Types of exercises available."""
    FLASHCARD = "flashcard"
    MULTIPLE_CHOICE = "multiple_choice"
    FILL_BLANK = "fill_blank"
    GRAMMAR_QUIZ = "grammar_quiz"
    COMPREHENSION = "comprehension"


@dataclass
class UserProgress:
    """Tracks user progress and performance."""
    user_id: str
    language: Language
    difficulty: Difficulty
    scores: Dict[ExerciseType, List[float]] = field(default_factory=dict)
    completion_dates: Dict[ExerciseType, List[str]] = field(default_factory=dict)

    def add_score(self, exercise_type: ExerciseType, score: float) -> None:
        """Add a score for a specific exercise type."""
        if exercise_type not in self.scores:
            self.scores[exercise_type] = []
            self.completion_dates[exercise_type] = []

        self.scores[exercise_type].append(score)
        self.completion_dates[exercise_type].append(
            datetime.datetime.now().isoformat()
        )

    def get_average_score(self, exercise_type: ExerciseType) -> float:
        """Calculate average score for an exercise type."""
        if exercise_type not in self.scores or not self.scores[exercise_type]:
            return 0.0
        return sum(self.scores[exercise_type]) / len(self.scores[exercise_type])

    def get_progress_summary(self) -> Dict[str, Any]:
        """Generate a summary of user progress."""
        summary = {
            "user_id": self.user_id,
            "language": self.language.value,
            "difficulty": self.difficulty.value,
            "total_exercises": sum(len(scores) for scores in self.scores.values()),
            "average_scores": {},
            "recent_activity": {}
        }

        for ex_type in ExerciseType:
            if ex_type in self.scores and self.scores[ex_type]:
                summary["average_scores"][ex_type.value] = self.get_average_score(ex_type)
                summary["recent_activity"][ex_type.value] = len(self.scores[ex_type])
            else:
                summary["average_scores"][ex_type.value] = 0.0
                summary["recent_activity"][ex_type.value] = 0

        return summary


class Exercise(ABC):
    """Abstract base class for all exercises."""

    def __init__(self, language: Language, difficulty: Difficulty):
        self.language = language
        self.difficulty = difficulty
        self.is_completed = False
        self.score = 0.0

    @abstractmethod
    def display_question(self) -> str:
        """Display the exercise question/prompt."""
        pass

    @abstractmethod
    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check user's answer and provide feedback."""
        pass

    @abstractmethod
    def get_correct_answer(self) -> str:
        """Get the correct answer for the exercise."""
        pass


class VocabularyExercise(Exercise):
    """Base class for vocabulary exercises."""

    def __init__(self, language: Language, difficulty: Difficulty, 
                 word: str, translation: str, example: str):
        super().__init__(language, difficulty)
        self.word = word
        self.translation = translation
        self.example = example


class FlashcardExercise(VocabularyExercise):
    """Flashcard exercise showing word and requiring translation."""

    def display_question(self) -> str:
        return f"Flashcard: {self.word}\nExample: {self.example}\nWhat is the translation?"

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        user_answer_lower = user_answer.strip().lower()
        correct_lower = self.translation.lower()

        if user_answer_lower == correct_lower:
            self.score = 1.0
            self.is_completed = True
            return True, "Correct! Well done!"
        else:
            self.score = 0.0
            return False, f"Incorrect. The correct translation is: {self.translation}"

    def get_correct_answer(self) -> str:
        return self.translation


class MultipleChoiceExercise(VocabularyExercise):
    """Multiple choice vocabulary exercise."""

    def __init__(self, language: Language, difficulty: Difficulty, 
                 word: str, translation: str, example: str, 
                 choices: List[str]):
        super().__init__(language, difficulty, word, translation, example)
        self.choices = choices
        self.correct_index = choices.index(translation) if translation in choices else 0

    def display_question(self) -> str:
        question = f"What is the translation of '{self.word}'?\n"
        for i, choice in enumerate(self.choices, 1):
            question += f"{i}. {choice}\n"
        return question

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        try:
            user_choice = int(user_answer.strip())
            if 1 <= user_choice <= len(self.choices):
                if self.choices[user_choice - 1] == self.translation:
                    self.score = 1.0
                    self.is_completed = True
                    return True, "Correct!"
                else:
                    self.score = 0.0
                    return False, f"Incorrect. The correct answer is: {self.translation}"
            else:
                self.score = 0.0
                return False, "Invalid choice number."
        except ValueError:
            self.score = 0.0
            return False, "Please enter a number corresponding to your choice."

    def get_correct_answer(self) -> str:
        return f"{self.correct_index + 1}. {self.translation}"


class FillBlankExercise(VocabularyExercise):
    """Fill in the blank vocabulary exercise."""

    def __init__(self, language: Language, difficulty: Difficulty,
                 word: str, translation: str, example: str):
        super().__init__(language, difficulty, word, translation, example)
        # Create a sentence with blank
        self.sentence_with_blank = example.replace(word, "_____")

    def display_question(self) -> str:
        return f"Fill in the blank:\n{self.sentence_with_blank}"

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        user_answer_lower = user_answer.strip().lower()
        correct_lower = self.word.lower()

        if user_answer_lower == correct_lower:
            self.score = 1.0
            self.is_completed = True
            return True, f"Correct! The word is '{self.word}'."
        else:
            self.score = 0.0
            return False, f"Incorrect. The correct word is: {self.word}"

    def get_correct_answer(self) -> str:
        return self.word


class GrammarExercise(Exercise):
    """Grammar quiz exercise."""

    def __init__(self, language: Language, difficulty: Difficulty,
                 question: str, correct_answer: str, options: List[str],
                 grammar_topic: str, explanation: str):
        super().__init__(language, difficulty)
        self.question = question
        self.correct_answer = correct_answer
        self.options = options
        self.grammar_topic = grammar_topic
        self.explanation = explanation

    def display_question(self) -> str:
        question_text = f"Grammar ({self.grammar_topic}): {self.question}\n"
        for i, option in enumerate(self.options, 1):
            question_text += f"{i}. {option}\n"
        return question_text

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        try:
            user_choice = int(user_answer.strip())
            if 1 <= user_choice <= len(self.options):
                if self.options[user_choice - 1] == self.correct_answer:
                    self.score = 1.0
                    self.is_completed = True
                    return True, f"Correct! {self.explanation}"
                else:
                    self.score = 0.0
                    return False, f"Incorrect. {self.explanation}"
            else:
                self.score = 0.0
                return False, "Invalid choice number."
        except ValueError:
            self.score = 0.0
            return False, "Please enter a number corresponding to your choice."

    def get_correct_answer(self) -> str:
        return self.correct_answer


class ComprehensionExercise(Exercise):
    """Reading comprehension exercise."""

    def __init__(self, language: Language, difficulty: Difficulty,
                 passage: str, questions: List[Dict[str, Any]]):
        super().__init__(language, difficulty)
        self.passage = passage
        self.questions = questions
        self.current_question_index = 0
        self.correct_answers = 0

    def display_question(self) -> str:
        if self.current_question_index == 0:
            return f"Reading Passage:\n{self.passage}\n\nQuestion 1: {self.questions[0]['question']}"
        elif self.current_question_index < len(self.questions):
            return f"Question {self.current_question_index + 1}: {self.questions[self.current_question_index]['question']}"
        else:
            return "All questions completed!"

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        if self.current_question_index >= len(self.questions):
            return False, "No more questions to answer."

        current_q = self.questions[self.current_question_index]
        user_answer_lower = user_answer.strip().lower()
        correct_lower = current_q['answer'].lower()

        if user_answer_lower == correct_lower:
            self.correct_answers += 1
            feedback = f"Correct! {current_q.get('explanation', 'Well done!')}"
        else:
            feedback = f"Incorrect. The correct answer is: {current_q['answer']}"

        self.current_question_index += 1

        # Calculate final score when all questions are answered
        if self.current_question_index >= len(self.questions):
            self.score = self.correct_answers / len(self.questions)
            self.is_completed = True

        return user_answer_lower == correct_lower, feedback

    def get_correct_answer(self) -> str:
        if self.current_question_index < len(self.questions):
            return self.questions[self.current_question_index]['answer']
        return "All questions answered"


class ExerciseFactory:
    """Factory class to create exercises based on language and difficulty."""

    # Sample data for exercises
    VOCAB_DATA = {
        Language.ENGLISH: {
            Difficulty.BEGINNER: [
                {"word": "hello", "translation": "hola", "example": "Hello, how are you?"},
                {"word": "goodbye", "translation": "adiós", "example": "Goodbye, see you tomorrow!"},
