            Difficulty.INTERMEDIATE: [
                {"word": "opportunity", "translation": "oportunidad", "example": "This is a great opportunity."},
                {"word": "challenge", "translation": "desafío", "example": "This project is a challenge."},
            ],
        },
        Language.SPANISH: {
            Difficulty.BEGINNER: [
                {"word": "hola", "translation": "hello", "example": "Hola, ¿cómo estás?"},
                {"word": "adiós", "translation": "goodbye", "example": "Adiós, hasta mañana."},
            ],
        },
    }

    GRAMMAR_DATA = {
        Language.ENGLISH: {
