                {
                    "question": "Choose the correct verb form: She ___ to school every day.",
                    "options": ["go", "goes", "going", "went"],
                    "answer": "goes",
                    "topic": "Present Simple",
                    "explanation": "Third person singular takes 's' in present simple."
                },
            ],
        },
    }

    COMPREHENSION_DATA = {
        Language.ENGLISH: {
            Difficulty.BEGINNER: [
                {
                    "passage": "The cat sat on the mat. It was a happy cat. The mat was red.",
                    "questions": [
                        {"question": "Where did the cat sit?", "answer": "on the mat", "explanation": "The first sentence says 'The cat sat on the mat.'"},
                        {"question": "What color was the mat?", "answer": "red", "explanation": "The last sentence says 'The mat was red.'"},
                    ]
                },
            ],
        },
    }

    @classmethod
    def create_exercise(cls, exercise_type: ExerciseType, language: Language, 
                       difficulty: Difficulty) -> Optional[Exercise]:
        """Create an exercise of specified type, language, and difficulty."""

        if language not in cls.VOCAB_DATA:
            return None

        if difficulty not in cls.VOCAB_DATA[language]:
            return None

        if exercise_type == ExerciseType.FLASHCARD:
            vocab_item = random.choice(cls.VOCAB_DATA[language][difficulty])
            return FlashcardExercise(
                language, difficulty,
                vocab_item["word"], vocab_item["translation"], vocab_item["example"]
            )

        elif exercise_type == ExerciseType.MULTIPLE_CHOICE:
            vocab_item = random.choice(cls.VOCAB_DATA[language][difficulty])
            # Generate incorrect choices
            all_words = [item["translation"] for item in cls.VOCAB_DATA[language][difficulty]]
            incorrect = [w for w in all_words if w != vocab_item["translation"]]
            choices = [vocab_item["translation"]] + random.sample(incorrect, min(3, len(incorrect)))
            random.shuffle(choices)

            return MultipleChoiceExercise(
                language, difficulty,
                vocab_item["word"], vocab_item["translation"], vocab_item["example"], choices
            )

        elif exercise_type == ExerciseType.FILL_BLANK:
            vocab_item = random.choice(cls.VOCAB_DATA[language][difficulty])
            return FillBlankExercise(
                language, difficulty,
                vocab_item["word"], vocab_item["translation"], vocab_item["example"]
            )

        elif exercise_type == ExerciseType.GRAMMAR_QUIZ:
            if language in cls.GRAMMAR_DATA and difficulty in cls.GRAMMAR_DATA[language]:
                grammar_item = random.choice(cls.GRAMMAR_DATA[language][difficulty])
                return GrammarExercise(
                    language, difficulty,
                    grammar_item["question"], grammar_item["answer"],
                    grammar_item["options"], grammar_item["topic"], grammar_item["explanation"]
                )

        elif exercise_type == ExerciseType.COMPREHENSION:
            if language in cls.COMPREHENSION_DATA and difficulty in cls.COMPREHENSION_DATA[language]:
                comp_item = random.choice(cls.COMPREHENSION_DATA[language][difficulty])
                return ComprehensionExercise(
                    language, difficulty,
                    comp_item["passage"], comp_item["questions"]
                )

        return None


