import pygame
import random
import math
import json
import time
from abc import ABC, abstractmethod
from typing import List, Dict, Tuple, Optional, Any
from dataclasses import dataclass, field
from enum import Enum

# ====================== Core Game Systems ======================

class GameState(Enum):
    """Game states for the arena."""
    MENU = "menu"
    PLAYING = "playing"
    PAUSED = "paused"
    GAME_OVER = "game_over"

class Team(Enum):
    """Teams in the arena."""
    RED = "red"
    BLUE = "blue"

class RobotRole(Enum):
    """Roles for AI-controlled robots."""
    ASSAULT = "assault"
    DEFENDER = "defender"
    SUPPORT = "support"
    SCOUT = "scout"

class WeaponType(Enum):
    """Types of weapons available."""
    RIFLE = "rifle"
    SHOTGUN = "shotgun"
    SNIPER = "sniper"
    MELEE = "melee"
    GRENADE = "grenade"

class ObjectiveType(Enum):
    """Types of team objectives."""
    CAPTURE_FLAG = "capture_flag"
    DEFEND_BASE = "defend_base"
    ESCORT_PAYLOAD = "escort_payload"
    CONTROL_POINT = "control_point"

# ====================== Core Classes ======================

@dataclass
class Vector2D:
    """2D vector for positions and movement."""
    x: float
    y: float

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def length(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        length = self.length()
        if length > 0:
            return Vector2D(self.x/length, self.y/length)
        return Vector2D(0, 0)

@dataclass
class Weapon:
    """Weapon class for robots."""
    name: str
    weapon_type: WeaponType
    damage: int
    range: float
    fire_rate: float
    ammo: int
    max_ammo: int

    def can_fire(self) -> bool:
        return self.ammo > 0

    def fire(self):
        if self.ammo > 0:
            self.ammo -= 1
            return self.damage
        return 0

    def reload(self):
        self.ammo = self.max_ammo

@dataclass
class PowerUp:
    """Power-up items in the arena."""
    position: Vector2D
    type: str
    effect: str
    duration: float
    active: bool = True

    def apply_effect(self, robot):
        """Apply power-up effect to robot."""
        if self.type == "health":
            robot.health = min(robot.max_health, robot.health + 50)
        elif self.type == "damage_boost":
            robot.damage_multiplier = 2.0
        elif self.type == "speed_boost":
            robot.speed_multiplier = 1.5
        self.active = False

@dataclass
class Objective:
    """Team objective in the arena."""
    objective_type: ObjectiveType
    position: Vector2D
    team: Optional[Team] = None
    progress: float = 0.0
    max_progress: float = 100.0
    active: bool = True

    def update(self, robot_team: Team) -> bool:
        """Update objective progress."""
        if not self.active:
            return False

        if self.team is None or self.team == robot_team:
            self.progress += 1.0
            if self.progress >= self.max_progress:
                self.active = False
                return True
        return False

# ====================== AI Systems ======================

class AIStrategy(ABC):
    """Abstract base class for AI strategies."""

    @abstractmethod
    def decide_action(self, robot, game_state) -> Dict[str, Any]:
        """Decide the next action for the robot."""
        pass

class AggressiveStrategy(AIStrategy):
    """Aggressive AI strategy."""

    def decide_action(self, robot, game_state) -> Dict[str, Any]:
        enemies = [r for r in game_state.robots if r.team != robot.team]
        if enemies:
            target = min(enemies, key=lambda e: (e.position - robot.position).length())
            return {
                "action": "attack",
                "target": target,
                "move_to": target.position
            }
        return {"action": "patrol", "target": None}

class DefensiveStrategy(AIStrategy):
    """Defensive AI strategy."""

    def decide_action(self, robot, game_state) -> Dict[str, Any]:
        objectives = [o for o in game_state.objectives if o.team == robot.team]
        if objectives:
            objective = objectives[0]
            return {
                "action": "defend",
                "target": objective,
                "move_to": objective.position
            }
        return {"action": "patrol", "target": None}

class AdaptiveDifficulty:
    """Adaptive difficulty system."""

