import json
import random
import datetime
from abc import ABC, abstractmethod
from typing import Dict, List, Tuple, Optional, Any
from dataclasses import dataclass, field
from enum import Enum
import time

# ====================== Data Models ======================

class DifficultyLevel(Enum):
    """Enum representing difficulty levels for exercises."""
    BEGINNER = "beginner"
    INTERMEDIATE = "intermediate"
    ADVANCED = "advanced"

class Language(Enum):
    """Enum representing supported languages."""
    ENGLISH = "english"
    SPANISH = "spanish"
    FRENCH = "french"
    GERMAN = "german"

@dataclass
class UserProgress:
    """Data class to track user's progress and scores."""
    user_id: str
    language: Language
    vocabulary_scores: List[Dict] = field(default_factory=list)
    grammar_scores: List[Dict] = field(default_factory=list)
    comprehension_scores: List[Dict] = field(default_factory=list)

    def add_vocabulary_score(self, score: float, difficulty: DifficultyLevel):
        """Add a vocabulary exercise score to progress tracking."""
        self.vocabulary_scores.append({
            "score": score,
            "difficulty": difficulty.value,
            "timestamp": datetime.datetime.now().isoformat()
        })

    def add_grammar_score(self, score: float, difficulty: DifficultyLevel):
        """Add a grammar exercise score to progress tracking."""
        self.grammar_scores.append({
            "score": score,
            "difficulty": difficulty.value,
            "timestamp": datetime.datetime.now().isoformat()
        })

    def add_comprehension_score(self, score: float, difficulty: DifficultyLevel):
        """Add a comprehension exercise score to progress tracking."""
        self.comprehension_scores.append({
            "score": score,
            "difficulty": difficulty.value,
            "timestamp": datetime.datetime.now().isoformat()
        })

    def get_analytics(self) -> Dict[str, Any]:
        """Calculate and return analytics based on user's performance."""
        def calculate_stats(scores: List[Dict]) -> Dict:
            if not scores:
                return {"average": 0, "best": 0, "total_exercises": 0}
            avg = sum(s["score"] for s in scores) / len(scores)
            best = max(s["score"] for s in scores)
            return {
                "average": round(avg, 2),
                "best": round(best, 2),
                "total_exercises": len(scores)
            }

        return {
            "vocabulary": calculate_stats(self.vocabulary_scores),
            "grammar": calculate_stats(self.grammar_scores),
            "comprehension": calculate_stats(self.comprehension_scores)
        }

# ====================== Base Exercise Classes ======================

class Exercise(ABC):
    """Abstract base class for all types of exercises."""

    def __init__(self, language: Language, difficulty: DifficultyLevel):
        self.language = language
        self.difficulty = difficulty

    @abstractmethod
    def display_question(self) -> str:
        """Display the exercise question to the user."""
        pass

    @abstractmethod
    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check the user's answer and return correctness and feedback."""
        pass

# ====================== Vocabulary Module ======================

class VocabularyFlashcard(Exercise):
    """Vocabulary exercise using flashcard format."""

    def __init__(self, language: Language, difficulty: DifficultyLevel, 
                 word: str, translation: str, example: str = ""):
        super().__init__(language, difficulty)
        self.word = word
        self.translation = translation
        self.example = example

    def display_question(self) -> str:
        """Display the word and ask for translation."""
        return f"Translate the word: '{self.word}'"

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check if the user's translation is correct."""
        is_correct = user_answer.lower() == self.translation.lower()
        feedback = f"Correct! '{self.word}' means '{self.translation}'"
        if not is_correct:
            feedback = f"Incorrect. '{self.word}' means '{self.translation}'"
        if self.example:
            feedback += f"\nExample: {self.example}"
        return is_correct, feedback

class VocabularyMultipleChoice(Exercise):
    """Vocabulary exercise using multiple-choice format."""

    def __init__(self, language: Language, difficulty: DifficultyLevel,
                 question: str, correct_answer: str, options: List[str]):
        super().__init__(language, difficulty)
        self.question = question
        self.correct_answer = correct_answer
        self.options = options
        random.shuffle(self.options)

    def display_question(self) -> str:
        """Display the multiple-choice question."""
        options_str = "\n".join(f"{i+1}. {opt}" for i, opt in enumerate(self.options))
        return f"{self.question}\n{options_str}"

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check if the user selected the correct option."""
        try:
            option_index = int(user_answer) - 1
            if 0 <= option_index < len(self.options):
                selected = self.options[option_index]
                is_correct = selected == self.correct_answer
                feedback = f"Correct! {self.correct_answer} is the right answer."
                if not is_correct:
                    feedback = f"Incorrect. The right answer is: {self.correct_answer}"
                return is_correct, feedback
        except ValueError:
            pass
        return False, f"Please enter a number between 1 and {len(self.options)}"

class VocabularyFillBlank(Exercise):
    """Vocabulary exercise using fill-in-the-blank format."""

    def __init__(self, language: Language, difficulty: DifficultyLevel,
                 sentence: str, blank_word: str, hint: str = ""):
        super().__init__(language, difficulty)
        self.sentence = sentence
        self.blank_word = blank_word
        self.hint = hint

    def display_question(self) -> str:
        """Display the sentence with blank."""
        display_sentence = self.sentence.replace(self.blank_word, "_____")
        question = f"Fill in the blank: {display_sentence}"
        if self.hint:
            question += f"\nHint: {self.hint}"
        return question

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check if the user filled the blank correctly."""
        is_correct = user_answer.lower() == self.blank_word.lower()
        feedback = f"Correct! The word is '{self.blank_word}'"
        if not is_correct:
            feedback = f"Incorrect. The correct word is '{self.blank_word}'"
        return is_correct, feedback

# ====================== Grammar Module ======================

class GrammarQuiz(Exercise):
    """Grammar exercise with various question types."""

    def __init__(self, language: Language, difficulty: DifficultyLevel,
                 question: str, correct_answer: str, explanation: str,
                 question_type: str = "multiple_choice", options: List[str] = None):
        super().__init__(language, difficulty)
        self.question = question
        self.correct_answer = correct_answer
        self.explanation = explanation
        self.question_type = question_type
        self.options = options or []
        if self.question_type == "multiple_choice" and self.options:
            random.shuffle(self.options)

    def display_question(self) -> str:
        """Display the grammar question."""
        if self.question_type == "multiple_choice" and self.options:
            options_str = "\n".join(f"{i+1}. {opt}" for i, opt in enumerate(self.options))
            return f"{self.question}\n{options_str}"
        return self.question

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check the user's answer and provide detailed feedback."""
        is_correct = False

        if self.question_type == "multiple_choice":
            try:
                option_index = int(user_answer) - 1
                if 0 <= option_index < len(self.options):
                    selected = self.options[option_index]
                    is_correct = selected == self.correct_answer
            except ValueError:
                pass
        else:
            # For open-ended questions, allow partial matches
            is_correct = user_answer.lower().strip() == self.correct_answer.lower().strip()

        feedback = f"{'Correct!' if is_correct else 'Incorrect.'}\n"
        feedback += f"Explanation: {self.explanation}"

        return is_correct, feedback

# ====================== Comprehension Module ======================

class ReadingComprehension(Exercise):
    """Reading comprehension exercise with passage and questions."""

    def __init__(self, language: Language, difficulty: DifficultyLevel,
                 passage: str, questions: List[Dict[str, str]]):
        super().__init__(language, difficulty)
        self.passage = passage
        self.questions = questions
        self.current_question_index = 0

    def display_question(self) -> str:
        """Display the passage and current question."""
        if self.current_question_index == 0:
            return f"Read the following passage:\n\n{self.passage}\n\n" + \
                   f"Question 1: {self.questions[0]['question']}"

        if self.current_question_index < len(self.questions):
            return f"Question {self.current_question_index + 1}: " + \
                   self.questions[self.current_question_index]['question']

        return "No more questions."

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check the answer for the current question."""
        if self.current_question_index >= len(self.questions):
            return False, "No more questions available."

        current_q = self.questions[self.current_question_index]
        is_correct = user_answer.lower().strip() == current_q['answer'].lower().strip()

        # Move to next question
        self.current_question_index += 1

        feedback = f"{'Correct!' if is_correct else 'Incorrect.'}\n"
