        feedback = f"Correct! '{self.word}' means '{self.translation}'"
        if not is_correct:
            feedback = f"Incorrect. '{self.word}' means '{self.translation}'"
        if self.example:
            feedback += f"\nExample: {self.example}"
        return is_correct, feedback

class VocabularyMultipleChoice(Exercise):
    """Vocabulary exercise using multiple-choice format."""

    def __init__(self, language: Language, difficulty: DifficultyLevel,
                 question: str, correct_answer: str, options: List[str]):
        super().__init__(language, difficulty)
        self.question = question
        self.correct_answer = correct_answer
        self.options = options
        random.shuffle(self.options)

    def display_question(self) -> str:
        """Display the multiple-choice question."""
        options_str = "\n".join(f"{i+1}. {opt}" for i, opt in enumerate(self.options))
        return f"{self.question}\n{options_str}"

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check if the user selected the correct option."""
        try:
            option_index = int(user_answer) - 1
            if 0 <= option_index < len(self.options):
                selected = self.options[option_index]
                is_correct = selected == self.correct_answer
                feedback = f"Correct! {self.correct_answer} is the right answer."
                if not is_correct:
                    feedback = f"Incorrect. The right answer is: {self.correct_answer}"
                return is_correct, feedback
        except ValueError:
            pass
        return False, f"Please enter a number between 1 and {len(self.options)}"

class VocabularyFillBlank(Exercise):
    """Vocabulary exercise using fill-in-the-blank format."""

    def __init__(self, language: Language, difficulty: DifficultyLevel,
                 sentence: str, blank_word: str, hint: str = ""):
        super().__init__(language, difficulty)
        self.sentence = sentence
        self.blank_word = blank_word
        self.hint = hint

    def display_question(self) -> str:
        """Display the sentence with blank."""
        display_sentence = self.sentence.replace(self.blank_word, "_____")
        question = f"Fill in the blank: {display_sentence}"
        if self.hint:
            question += f"\nHint: {self.hint}"
        return question

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check if the user filled the blank correctly."""
        is_correct = user_answer.lower() == self.blank_word.lower()
        feedback = f"Correct! The word is '{self.blank_word}'"
        if not is_correct:
            feedback = f"Incorrect. The correct word is '{self.blank_word}'"
        return is_correct, feedback

