class GrammarQuiz(Exercise):
    """Grammar exercise with various question types."""

    def __init__(self, language: Language, difficulty: DifficultyLevel,
                 question: str, correct_answer: str, explanation: str,
                 question_type: str = "multiple_choice", options: List[str] = None):
        super().__init__(language, difficulty)
        self.question = question
        self.correct_answer = correct_answer
        self.explanation = explanation
        self.question_type = question_type
        self.options = options or []
        if self.question_type == "multiple_choice" and self.options:
            random.shuffle(self.options)

    def display_question(self) -> str:
        """Display the grammar question."""
        if self.question_type == "multiple_choice" and self.options:
            options_str = "\n".join(f"{i+1}. {opt}" for i, opt in enumerate(self.options))
            return f"{self.question}\n{options_str}"
        return self.question

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check the user's answer and provide detailed feedback."""
        is_correct = False

        if self.question_type == "multiple_choice":
            try:
                option_index = int(user_answer) - 1
                if 0 <= option_index < len(self.options):
                    selected = self.options[option_index]
                    is_correct = selected == self.correct_answer
            except ValueError:
                pass
        else:
            # For open-ended questions, allow partial matches
            is_correct = user_answer.lower().strip() == self.correct_answer.lower().strip()

        feedback = f"{'Correct!' if is_correct else 'Incorrect.'}\n"
        feedback += f"Explanation: {self.explanation}"

        return is_correct, feedback

