class ReadingComprehension(Exercise):
    """Reading comprehension exercise with passage and questions."""

    def __init__(self, language: Language, difficulty: DifficultyLevel,
                 passage: str, questions: List[Dict[str, str]]):
        super().__init__(language, difficulty)
        self.passage = passage
        self.questions = questions
        self.current_question_index = 0

    def display_question(self) -> str:
        """Display the passage and current question."""
        if self.current_question_index == 0:
            return f"Read the following passage:\n\n{self.passage}\n\n" + \
                   f"Question 1: {self.questions[0]['question']}"

        if self.current_question_index < len(self.questions):
            return f"Question {self.current_question_index + 1}: " + \
                   self.questions[self.current_question_index]['question']

        return "No more questions."

    def check_answer(self, user_answer: str) -> Tuple[bool, str]:
        """Check the answer for the current question."""
        if self.current_question_index >= len(self.questions):
            return False, "No more questions available."

        current_q = self.questions[self.current_question_index]
        is_correct = user_answer.lower().strip() == current_q['answer'].lower().strip()

        # Move to next question
        self.current_question_index += 1

        feedback = f"{'Correct!' if is_correct else 'Incorrect.'}\n"
        feedback += f"Correct answer: {current_q['answer']}"

        return is_correct, feedback

    def has_more_questions(self) -> bool:
        """Check if there are more questions."""
        return self.current_question_index < len(self.questions)

