# ====================== Data Models ======================

class ProjectPhase(Enum):
    """Enum representing project phases with dependencies."""
    SETUP = "project_setup"
    TEAM_MANAGEMENT = "team_management"
    TASK_EXECUTION = "task_execution"
    ISSUE_RESOLUTION = "issue_resolution"
    DELIVERY = "project_delivery"

class TaskStatus(Enum):
    """Enum representing task statuses."""
    PENDING = "pending"
    IN_PROGRESS = "in_progress"
    COMPLETED = "completed"
    BLOCKED = "blocked"
    DELAYED = "delayed"

class TeamMemberSkill(Enum):
    """Enum representing team member skills."""
    FRONTEND = "frontend_development"
    BACKEND = "backend_development"
    DATABASE = "database_management"
    DEVOPS = "devops"
    TESTING = "testing"
    DESIGN = "ui_ux_design"
    PROJECT_MANAGEMENT = "project_management"

class IssuePriority(Enum):
    """Enum representing issue priorities."""
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"

@dataclass
class Project:
    """Data class representing a software development project."""
    name: str
    scope: str = ""
    budget: float = 0.0
    timeline_days: int = 0
    start_date: Optional[datetime.datetime] = None
    current_phase: ProjectPhase = ProjectPhase.SETUP
    is_complete: bool = False
    quality_score: float = 100.0  # Starts at 100%
    tasks: List["Task"] = field(default_factory=list)
    team_members: List["TeamMember"] = field(default_factory=list)
    issues: List["Issue"] = field(default_factory=list)

    def setup_project(self, scope: str, budget: float, timeline_days: int) -> None:
        """Set up the project with scope, budget, and timeline."""
        if self.current_phase != ProjectPhase.SETUP:
            raise ValueError("Project setup can only be done in SETUP phase")

        self.scope = scope
        self.budget = budget
        self.timeline_days = timeline_days
        self.start_date = datetime.datetime.now()
        self.current_phase = ProjectPhase.TEAM_MANAGEMENT
        print(f"Project '{self.name}' setup complete!")

    def add_task(self, task: "Task") -> None:
        """Add a task to the project plan."""
        self.tasks.append(task)

    def add_team_member(self, member: "TeamMember") -> None:
        """Add a team member to the project."""
        self.team_members.append(member)

    def add_issue(self, issue: "Issue") -> None:
        """Add an issue to track."""
        self.issues.append(issue)

    def advance_phase(self) -> bool:
        """Attempt to advance to the next project phase."""
        phase_order = list(ProjectPhase)
        current_index = phase_order.index(self.current_phase)

        if current_index >= len(phase_order) - 1:
            return False

        next_phase = phase_order[current_index + 1]

        # Check phase-specific requirements
        if next_phase == ProjectPhase.TEAM_MANAGEMENT:
            if not self.scope or self.budget <= 0 or self.timeline_days <= 0:
                print("Cannot advance: Project setup incomplete")
                return False
        elif next_phase == ProjectPhase.TASK_EXECUTION:
            if not any(member.assigned_tasks for member in self.team_members):
                print("Cannot advance: No tasks assigned to team members")
                return False
        elif next_phase == ProjectPhase.DELIVERY:
            if not all(task.status == TaskStatus.COMPLETED for task in self.tasks):
                print("Cannot advance: Not all tasks are completed")
                return False
            if self.quality_score < 70.0:
                print(f"Cannot advance: Quality score {self.quality_score:.1f}% is below 70%")
                return False

        self.current_phase = next_phase
        print(f"Advanced to {next_phase.value.replace('_', ' ').title()} phase")
        return True

    def calculate_progress(self) -> Dict[str, Any]:
        """Calculate project progress metrics."""
        completed_tasks = sum(1 for task in self.tasks if task.status == TaskStatus.COMPLETED)
        total_tasks = len(self.tasks)

        elapsed_days = 0
        if self.start_date:
            elapsed_days = (datetime.datetime.now() - self.start_date).days

        budget_used = sum(task.actual_cost for task in self.tasks)
        budget_percentage = (budget_used / self.budget * 100) if self.budget > 0 else 0

        return {
            "phase": self.current_phase.value,
            "task_completion": f"{completed_tasks}/{total_tasks}",
            "task_percentage": (completed_tasks / total_tasks * 100) if total_tasks > 0 else 0,
            "days_elapsed": elapsed_days,
            "days_remaining": max(0, self.timeline_days - elapsed_days),
            "budget_used": budget_used,
            "budget_remaining": max(0, self.budget - budget_used),
            "budget_percentage": budget_percentage,
            "quality_score": self.quality_score,
            "active_issues": sum(1 for issue in self.issues if not issue.is_resolved),
            "team_size": len(self.team_members)
        }

    def attempt_delivery(self) -> bool:
        """Attempt to deliver the project and calculate final score."""
        if self.current_phase != ProjectPhase.DELIVERY:
            print(f"Cannot deliver: Current phase is {self.current_phase.value}")
            return False

        progress = self.calculate_progress()

        # Calculate delivery score
