class ExerciseManager:
    """Manages exercises and user progress."""

    def __init__(self):
        self.exercises: Dict[str, Exercise] = {}
        self.user_progress: Dict[str, Dict[str, Any]] = {}

    def add_exercise(self, exercise: Exercise):
        """Add a new exercise to the system."""
        self.exercises[exercise.id] = exercise

    def get_exercise(self, exercise_id: str) -> Optional[Exercise]:
        """Retrieve an exercise by ID."""
        return self.exercises.get(exercise_id)

    def get_exercises_by_difficulty(self, difficulty: DifficultyLevel) -> List[Exercise]:
        """Get all exercises of a specific difficulty level."""
        return [ex for ex in self.exercises.values() if ex.difficulty == difficulty]

    def update_user_progress(self, user_id: str, exercise_id: str, score: float):
        """Update user progress after completing an exercise."""
        if user_id not in self.user_progress:
            self.user_progress[user_id] = {"completed_exercises": {}, "total_score": 0}

