class ProportionalReductionStrategy(BudgetOptimizerStrategy):
    """Strategy that suggests proportional reductions based on spending patterns"""

    def optimize(self, users: List[User], expenses: List[Expense], goals: List[FinancialGoal]) -> Dict[str, Any]:
        total_expenses = sum(exp.amount for exp in expenses)
        user_expenses = {user.user_id: 0 for user in users}

        for exp in expenses:
            if exp.user_id in user_expenses:
                user_expenses[exp.user_id] += exp.amount

        suggestions = []
        for user in users:
            user_total = user_expenses.get(user.user_id, 0)
            if user_total > 0:
                reduction_pct = min(20, (user_total / total_expenses) * 100) if total_expenses > 0 else 10
                suggestions.append({
                    "user_id": user.user_id,
                    "username": user.username,
                    "suggestion": f"Reduce spending by {reduction_pct:.1f}% based on your contribution to total expenses",
                    "estimated_savings": user_total * (reduction_pct / 100)
                })

        return {
            "strategy": "proportional_reduction",
            "suggestions": suggestions,
            "total_potential_savings": sum(s["estimated_savings"] for s in suggestions)
        }

class CategoryBasedStrategy(BudgetOptimizerStrategy):
    """Strategy that suggests category-specific optimizations"""

    def optimize(self, users: List[User], expenses: List[Expense], goals: List[FinancialGoal]) -> Dict[str, Any]:
