class SymptomAnalysisAgent(Agent):
    """Agent responsible for analyzing patient symptoms and health data"""

    def __init__(self):
        super().__init__("SymptomAnalysisAgent")
        # Knowledge base for symptom patterns
        self.symptom_patterns = {
            DiseaseType.DIABETES: {
                "frequent_urination": ["polyuria", "nocturia"],
                "increased_thirst": ["polydipsia"],
                "fatigue": ["tiredness", "lethargy"],
                "blurred_vision": []
            },
            DiseaseType.HYPERTENSION: {
                "headache": [],
                "dizziness": [],
                "chest_pain": ["angina"],
                "shortness_of_breath": ["dyspnea"]
            },
            DiseaseType.CHRONIC_HEART_DISEASE: {
                "chest_pain": ["angina", "tightness"],
                "shortness_of_breath": ["dyspnea"],
                "fatigue": [],
                "swelling": ["edema"]
            }
        }

    def analyze_symptoms(self, symptoms: List[Symptom], disease_type: DiseaseType) -> Dict:
        """Analyze symptoms and return assessment"""
        self.log(f"Analyzing {len(symptoms)} symptoms for {disease_type.value}")

        assessment = {
            "overall_severity": SeverityLevel.MILD,
            "urgent_issues": [],
            "stability": "stable",
            "recommendations": []
        }

        # Check for critical symptoms
        critical_symptoms = []
        for symptom in symptoms:
            if symptom.severity in [SeverityLevel.SEVERE, SeverityLevel.CRITICAL]:
                critical_symptoms.append(symptom.name)

        if critical_symptoms:
            assessment["urgent_issues"] = critical_symptoms
            assessment["stability"] = "unstable"
            assessment["overall_severity"] = SeverityLevel.SEVERE

        # Generate recommendations based on symptoms
        if disease_type == DiseaseType.DIABETES:
            for symptom in symptoms:
                if symptom.name in ["frequent_urination", "increased_thirst"]:
                    assessment["recommendations"].append(
                        "Check blood glucose levels more frequently"
                    )
        elif disease_type == DiseaseType.HYPERTENSION:
            for symptom in symptoms:
                if symptom.name in ["severe_headache", "chest_pain"]:
                    assessment["recommendations"].append(
                        "Monitor blood pressure immediately"
                    )

        return assessment

    def process(self, data: Dict) -> Dict:
        """Process health data and symptoms"""
        symptoms = [Symptom(**s) if isinstance(s, dict) else s for s in data.get("symptoms", [])]
        disease_type = DiseaseType(data.get("disease_type", "diabetes"))

        assessment = self.analyze_symptoms(symptoms, disease_type)

        # Add health data analysis
        health_data = data.get("health_data", {})
        if health_data:
            if disease_type == DiseaseType.DIABETES and health_data.get("blood_glucose"):
                bg = health_data["blood_glucose"]
                if bg > 180:
                    assessment["recommendations"].append("High blood glucose detected")
                    assessment["stability"] = "unstable"

            elif disease_type == DiseaseType.HYPERTENSION and health_data.get("blood_pressure"):
                bp = health_data["blood_pressure"]
                if bp[0] > 140 or bp[1] > 90:
                    assessment["recommendations"].append("Elevated blood pressure detected")

        return assessment

class TreatmentRecommendationAgent(Agent):
    """Agent responsible for generating personalized treatment recommendations"""

    def __init__(self):
        super().__init__("TreatmentRecommendationAgent")
        # Treatment templates for different diseases and severity levels
        self.treatment_templates = self._initialize_templates()

    def _initialize_templates(self) -> Dict:
        """Initialize treatment templates for different diseases"""
        templates = {
            DiseaseType.DIABETES: {
                SeverityLevel.MILD: {
                    "medications": [
