                        )
                    ]
                }
            }
        }
        return templates

    def generate_treatment_plan(self, patient: Patient, assessment: Dict) -> TreatmentPlan:
        """Generate personalized treatment plan based on patient data and assessment"""
        self.log(f"Generating treatment plan for patient {patient.patient_id}")

        severity = assessment.get("overall_severity", SeverityLevel.MILD)
        template = self.treatment_templates.get(patient.disease_type, {}).get(severity)

        if not template:
            # Fallback to mild template
            template = self.treatment_templates.get(patient.disease_type, {}).get(SeverityLevel.MILD, {})

        # Create treatment plan
        plan_id = f"PLAN_{uuid.uuid4().hex[:8]}"
        plan = TreatmentPlan(
            plan_id=plan_id,
            patient_id=patient.patient_id,
            disease_type=patient.disease_type,
            medications=template.get("medications", []),
            dietary_recommendations=template.get("dietary", []),
            exercise_routines=template.get("exercise", []),
            created_date=datetime.date.today(),
            last_updated=datetime.datetime.now(),
            notes=f"Generated based on {severity.value} assessment"
        )

        return plan

    def adjust_medication(self, current_plan: TreatmentPlan, health_data: HealthData) -> TreatmentPlan:
        """Adjust medication based on health data"""
        self.log(f"Adjusting medication for plan {current_plan.plan_id}")

        updated_plan = TreatmentPlan(
            plan_id=current_plan.plan_id,
            patient_id=current_plan.patient_id,
            disease_type=current_plan.disease_type,
            medications=current_plan.medications.copy(),
            dietary_recommendations=current_plan.dietary_recommendations.copy(),
            exercise_routines=current_plan.exercise_routines.copy(),
            created_date=current_plan.created_date,
            last_updated=datetime.datetime.now(),
            status=current_plan.status,
            notes=current_plan.notes
        )

        # Adjust based on disease type
        if current_plan.disease_type == DiseaseType.DIABETES:
            if health_data.blood_glucose:
                bg = health_data.blood_glucose
                for med in updated_plan.medications:
                    if med.name == "Metformin":
                        if bg > 200:
                            # Increase dosage
                            med.current_dosage = med.dosage
                            med.dosage = "1000mg"
                            updated_plan.notes += f" | Increased Metformin due to high glucose ({bg})"
                        elif bg < 70:
                            # Decrease dosage
                            med.current_dosage = med.dosage
                            med.dosage = "500mg"
                            updated_plan.notes += f" | Decreased Metformin due to low glucose ({bg})"

        elif current_plan.disease_type == DiseaseType.HYPERTENSION:
            if health_data.blood_pressure:
                systolic, diastolic = health_data.blood_pressure
                for med in updated_plan.medications:
                    if med.name == "Lisinopril":
                        if systolic > 150:
                            med.current_dosage = med.dosage
                            med.dosage = "20mg"
                            updated_plan.notes += f" | Increased Lisinopril due to high BP ({systolic}/{diastolic})"

        return updated_plan

    def process(self, data: Dict) -> TreatmentPlan:
        """Process patient data and generate treatment plan"""
        patient_data = data.get("patient")
        assessment = data.get("assessment", {})

        if isinstance(patient_data, dict):
            patient = Patient(**patient_data)
        else:
            patient = patient_data

        if data.get("action") == "adjust":
            current_plan = data.get("current_plan")
            health_data = data.get("health_data")
            return self.adjust_medication(current_plan, health_data)
        else:
            return self.generate_treatment_plan(patient, assessment)

