# Music_Collaboration_Hub - A web-based platform for real-time music collaboration
# This implementation provides a comprehensive system with backend, frontend, and database components

import asyncio
import json
import uuid
import hashlib
import base64
from datetime import datetime
from typing import Dict, List, Optional, Any, Tuple
from enum import Enum
import numpy as np
from dataclasses import dataclass, field
from collections import defaultdict

# ============================================================================
# DATABASE MODELS (database_models.py)
# ============================================================================

@dataclass
class User:
    """User model for authentication and profile management"""
    id: str
    username: str
    email: str
    password_hash: str
    created_at: datetime
    profile_picture: Optional[str] = None
    preferences: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        """Convert user object to dictionary for serialization"""
        return {
            'id': self.id,
            'username': self.username,
            'email': self.email,
            'created_at': self.created_at.isoformat(),
            'profile_picture': self.profile_picture,
            'preferences': self.preferences
        }

@dataclass
class Project:
    """Music project model with version control support"""
    id: str
    name: str
    owner_id: str
    created_at: datetime
    updated_at: datetime
    collaborators: List[str] = field(default_factory=list)
    loops: List[Dict[str, Any]] = field(default_factory=list)
    chord_progressions: List[Dict[str, Any]] = field(default_factory=list)
    soundwave_data: Optional[Dict[str, Any]] = None
    version_history: List[Dict[str, Any]] = field(default_factory=list)
    settings: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        """Convert project object to dictionary for serialization"""
        return {
            'id': self.id,
            'name': self.name,
            'owner_id': self.owner_id,
            'created_at': self.created_at.isoformat(),
            'updated_at': self.updated_at.isoformat(),
            'collaborators': self.collaborators,
            'loops': self.loops,
            'chord_progressions': self.chord_progressions,
            'soundwave_data': self.soundwave_data,
            'version_history': self.version_history,
            'settings': self.settings
        }

@dataclass
class CollaborationSession:
    """Real-time collaboration session model"""
    id: str
    project_id: str
    participants: List[str] = field(default_factory=list)
    chat_messages: List[Dict[str, Any]] = field(default_factory=list)
    created_at: datetime = field(default_factory=datetime.now)
    last_activity: datetime = field(default_factory=datetime.now)

    def to_dict(self) -> Dict[str, Any]:
        """Convert collaboration session to dictionary"""
        return {
            'id': self.id,
            'project_id': self.project_id,
            'participants': self.participants,
            'chat_messages': self.chat_messages[-50:],  # Last 50 messages
            'created_at': self.created_at.isoformat(),
            'last_activity': self.last_activity.isoformat()
        }

# ============================================================================
# DATABASE LAYER (database.py)
# ============================================================================

class Database:
    """In-memory database for storing application data"""

    def __init__(self):
        self.users: Dict[str, User] = {}
        self.projects: Dict[str, Project] = {}
        self.sessions: Dict[str, CollaborationSession] = {}
        self.user_sessions: Dict[str, str] = {}  # user_id -> session_id

    def create_user(self, username: str, email: str, password: str) -> User:
        """Create a new user with hashed password"""
        user_id = str(uuid.uuid4())
        password_hash = hashlib.sha256(password.encode()).hexdigest()
        user = User(
            id=user_id,
            username=username,
            email=email,
            password_hash=password_hash,
            created_at=datetime.now()
        )
        self.users[user_id] = user
        return user

    def authenticate_user(self, email: str, password: str) -> Optional[User]:
        """Authenticate user by email and password"""
        password_hash = hashlib.sha256(password.encode()).hexdigest()
        for user in self.users.values():
            if user.email == email and user.password_hash == password_hash:
                return user
