            name=name,
            owner_id=owner_id,
            created_at=now,
            updated_at=now
        )
        self.projects[project_id] = project
        return project

    def get_user_projects(self, user_id: str) -> List[Project]:
        """Get all projects accessible by a user"""
        user_projects = []
        for project in self.projects.values():
            if project.owner_id == user_id or user_id in project.collaborators:
                user_projects.append(project)
        return user_projects

    def create_collaboration_session(self, project_id: str, user_id: str) -> CollaborationSession:
        """Create or join a collaboration session for a project"""
        # Check if session already exists
        for session in self.sessions.values():
            if session.project_id == project_id:
                if user_id not in session.participants:
                    session.participants.append(user_id)
                self.user_sessions[user_id] = session.id
                session.last_activity = datetime.now()
                return session

        # Create new session
        session_id = str(uuid.uuid4())
        session = CollaborationSession(
            id=session_id,
            project_id=project_id,
            participants=[user_id]
        )
        self.sessions[session_id] = session
        self.user_sessions[user_id] = session_id
        return session

    def add_chat_message(self, session_id: str, user_id: str, message: str) -> Dict[str, Any]:
