            chat_message = {
                'id': str(uuid.uuid4()),
                'user_id': user_id,
                'message': message,
                'timestamp': datetime.now().isoformat()
            }
            session.chat_messages.append(chat_message)
            session.last_activity = datetime.now()
            return chat_message
        return {}

