        neg_count = sum(1 for word in words if word in negative_words)

        total = pos_count + neg_count
        if total == 0:
            return 0.0

        # Normalize to -1 to 1 range
        return (pos_count - neg_count) / total

    def extract_keywords(self, content: str, num_keywords: int = 5) -> List[str]:
        """Extract most frequent words (excluding common stop words)."""
        stop_words = {'the', 'and', 'a', 'an', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by'}
        words = [word.lower() for word in content.split() if word.isalpha()]
        words = [word for word in words if word not in stop_words]

        # Get most common words
        word_counts = Counter(words)
        return [word for word, _ in word_counts.most_common(num_keywords)]


# ==================== Recommendation Engine ====================

class RecommendationEngine:
    """
    Engine for generating personalized news recommendations.
    Uses collaborative filtering and content-based filtering.
    """

    def __init__(self):
        self.user_profiles: Dict[str, Dict] = {}
        self.article_profiles: Dict[str, Dict] = {}

    def update_user_profile(self, user: User):
        """Update user profile based on interactions."""
        profile = {
            'interests': [cat.value for cat in user.interests],
            'click_history': user.click_history[-100:],  # Last 100 clicks
            'saved_articles': list(user.saved_articles),
            'feedback_scores': self._calculate_feedback_scores(user.feedback_history)
        }
        self.user_profiles[user.user_id] = profile

    def update_article_profile(self, article: Article):
        """Create/update article profile."""
        profile = {
            'category': article.category.value,
            'keywords': article.keywords,
            'sentiment': article.sentiment_score or 0.0,
            'popularity': 0  # Will be updated based on interactions
        }
        self.article_profiles[article.article_id] = profile

    def generate_recommendations(self, user: User, articles: List[Article], 
                                 num_recommendations: int = 10) -> List[Article]:
        """Generate personalized recommendations for a user."""
        if not articles:
            return []

        # Update user profile
        self.update_user_profile(user)

        # Score articles based on multiple factors
        scored_articles = []
        for article in articles:
            score = self._calculate_article_score(user, article)
            scored_articles.append((article, score))

        # Sort by score and return top recommendations
        scored_articles.sort(key=lambda x: x[1], reverse=True)
        return [article for article, _ in scored_articles[:num_recommendations]]

    def _calculate_article_score(self, user: User, article: Article) -> float:
        """Calculate recommendation score for an article."""
        score = 0.0

        # Interest match
        if article.category in user.interests:
            score += 2.0

        # Click history similarity
        if user.click_history:
            recent_clicks = user.click_history[-10:]
            # Simulate collaborative filtering (in real system would use proper algorithm)
            if any(click_id in self.article_profiles for click_id in recent_clicks):
                score += 1.0

        # Saved articles similarity
        if article.article_id in user.saved_articles:
            score += 3.0

        # Freshness
        days_old = (datetime.datetime.now() - article.publish_date).days
        if days_old < 1:
            score += 2.0
        elif days_old < 7:
            score += 1.0

        # Add some randomness for exploration
        score += random.uniform(0, 0.5)

        return score

    def _calculate_feedback_scores(self, feedback_history: List[Dict]) -> Dict[str, float]:
        """Calculate average feedback scores from user history."""
        if not feedback_history:
            return {'relevance': 0.5, 'accuracy': 0.5}

        relevance_scores = [fb['relevance_score'] for fb in feedback_history]
        accuracy_scores = [fb['accuracy_score'] for fb in feedback_history]

        return {
            'relevance': sum(relevance_scores) / len(relevance_scores),
            'accuracy': sum(accuracy_scores) / len(accuracy_scores)
        }


# ==================== Analytics Service ====================

class AnalyticsService:
    """Service for providing analytics and insights on news articles."""

    def __init__(self):
        self.article_metrics: Dict[str, Dict] = defaultdict(lambda: {
            'views': 0,
            'saves': 0,
            'shares': 0,
            'comments': 0,
            'avg_sentiment': 0.0
        })

    def record_interaction(self, article_id: str, interaction_type: str):
        """Record user interaction with an article."""
        if article_id in self.article_metrics:
            if interaction_type in self.article_metrics[article_id]:
                self.article_metrics[article_id][interaction_type] += 1

    def get_article_analytics(self, article_id: str) -> Dict:
        """Get analytics for a specific article."""
        return self.article_metrics.get(article_id, {})

    def get_popularity_trends(self, articles: List[Article], 
                               time_period: str = 'daily') -> List[Dict]:
        """Analyze popularity trends across articles."""
        # Simplified implementation - in production would use time-series data
        trending_articles = []

        for article in articles:
            metrics = self.article_metrics.get(article.article_id, {})
            popularity_score = (
                metrics.get('views', 0) * 0.3 +
                metrics.get('saves', 0) * 0.4 +
                metrics.get('shares', 0) * 0.3
            )

            if popularity_score > 0:
                trending_articles.append({
                    'article_id': article.article_id,
                    'title': article.title,
                    'popularity_score': popularity_score,
                    'trend': 'up' if popularity_score > 10 else 'stable'
                })

        return sorted(trending_articles, key=lambda x: x['popularity_score'], reverse=True)[:10]

    def analyze_emerging_topics(self, articles: List[Article]) -> List[Dict]:
        """Identify emerging topics based on recent articles."""
        keyword_counts = Counter()

        for article in articles:
            # Consider recent articles only (last 24 hours)
            if (datetime.datetime.now() - article.publish_date).days <= 1:
                for keyword in article.keywords:
                    keyword_counts[keyword] += 1

        return [
            {'keyword': keyword, 'count': count}
            for keyword, count in keyword_counts.most_common(10)
        ]


# ==================== Collaborative Workspace ====================

class CollaborativeWorkspace:
    """Manages collaborative features like discussions and sharing."""

    def __init__(self):
        self.discussions: Dict[str, DiscussionThread] = {}
        self.shared_articles: Dict[str, List[str]] = defaultdict(list)  # article_id -> [user_ids]

    def create_discussion(self, article_id: str) -> DiscussionThread:
        """Create a new discussion thread for an article."""
        if article_id not in self.discussions:
            self.discussions[article_id] = DiscussionThread(article_id=article_id)
        return self.discussions[article_id]

    def add_comment(self, article_id: str, user_id: str, 
                    content: str, parent_comment_id: Optional[str] = None) -> Comment:
        """Add a comment to an article's discussion thread."""
        if article_id not in self.discussions:
            self.create_discussion(article_id)

        comment = Comment(
            comment_id=str(uuid.uuid4()),
            article_id=article_id,
            user_id=user_id,
            content=content,
            timestamp=datetime.datetime.now(),
            parent_comment_id=parent_comment_id
        )

        self.discussions[article_id].add_comment(comment)
        return comment

    def share_article(self, article_id: str, from_user_id: str, to_user_ids: List[str]):
        """Share an article with other users."""
        if article_id not in self.shared_articles:
            self.shared_articles[article_id] = []

        # Record sharing for analytics
        self.shared_articles[article_id].extend(to_user_ids)

        # In production, would also send notifications to users
        return {
            'article_id': article_id,
            'shared_by': from_user_id,
            'shared_with': to_user_ids,
            'timestamp': datetime.datetime.now().isoformat()
        }

    def get_discussion(self, article_id: str) -> Optional[DiscussionThread]:
        """Get discussion thread for an article."""
        return self.discussions.get(article_id)


