    def execute_transaction(self, operations: List[Tuple[str, Dict]]) -> bool:
        pass

    @abstractmethod
    def backup(self) -> bool:
        pass

    @abstractmethod
    def restore(self, backup_id: str) -> bool:
        pass


class InMemoryDatabase(Database):
