# ================ BASE USER MANAGEMENT SYSTEM ================

class User:
    """User class for registration and profile management"""
    def __init__(self, username: str, email: str, password: str):
        self.user_id = str(uuid.uuid4())
        self.username = username
        self.email = email
        self._password = password  # In production, this should be hashed
        self.profile_picture: Optional[str] = None
        self.cultural_background: Dict[str, str] = {}
        self.interests: List[str] = []
        self.registration_date = datetime.now()
        self.is_active = True

    def update_profile(self, cultural_background: Dict[str, str], interests: List[str], profile_picture: Optional[str] = None):
        """Update user profile information"""
        self.cultural_background = cultural_background
        self.interests = interests
        if profile_picture:
            self.profile_picture = profile_picture

    def to_dict(self) -> Dict:
        """Convert user object to dictionary for serialization"""
        return {
            'user_id': self.user_id,
            'username': self.username,
            'email': self.email,
            'profile_picture': self.profile_picture,
            'cultural_background': self.cultural_background,
            'interests': self.interests,
            'registration_date': self.registration_date.isoformat(),
            'is_active': self.is_active
        }


class UserManager:
    """Manages user registration and authentication"""
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.sessions: Dict[str, str] = {}  # session_id -> user_id

    def register_user(self, username: str, email: str, password: str) -> Tuple[bool, str]:
        """Register a new user"""
        # Check if user already exists
        for user in self.users.values():
            if user.email == email:
                return False, "Email already registered"
            if user.username == username:
                return False, "Username already taken"

        # Create new user
        new_user = User(username, email, password)
        self.users[new_user.user_id] = new_user
        return True, new_user.user_id

    def login(self, email: str, password: str) -> Optional[str]:
        """Authenticate user and create session"""
        for user in self.users.values():
            if user.email == email and user._password == password:
                session_id = str(uuid.uuid4())
                self.sessions[session_id] = user.user_id
                return session_id
        return None

    def get_user_by_session(self, session_id: str) -> Optional[User]:
        """Retrieve user by session ID"""
        user_id = self.sessions.get(session_id)
        if user_id:
            return self.users.get(user_id)
        return None

    def update_user_profile(self, user_id: str, **kwargs) -> bool:
        """Update user profile information"""
        user = self.users.get(user_id)
        if not user:
            return False

        if 'cultural_background' in kwargs:
            user.cultural_background = kwargs['cultural_background']
        if 'interests' in kwargs:
            user.interests = kwargs['interests']
        if 'profile_picture' in kwargs:
            user.profile_picture = kwargs['profile_picture']

        return True

