class VirtualTour:
    """Virtual tour of cultural landmarks"""
    def __init__(self, tour_id: str, title: str, description: str, landmark_type: str):
        self.tour_id = tour_id
        self.title = title
        self.description = description
        self.landmark_type = landmark_type
        self.hotspots: List[Dict] = []
        self.audio_guides: List[Dict] = []
        self.ratings: List[float] = []

    def add_hotspot(self, x: float, y: float, z: float, info: str):
        """Add interactive hotspot to the tour"""
        hotspot = {
            'id': str(uuid.uuid4()),
            'position': {'x': x, 'y': y, 'z': z},
            'information': info,
            'timestamp': datetime.now().isoformat()
        }
        self.hotspots.append(hotspot)

    def add_audio_guide(self, title: str, audio_url: str, duration: int):
        """Add audio guide to the tour"""
        audio_guide = {
            'id': str(uuid.uuid4()),
            'title': title,
            'audio_url': audio_url,
            'duration': duration,
            'timestamp': datetime.now().isoformat()
        }
        self.audio_guides.append(audio_guide)

    def add_rating(self, rating: float):
        """Add user rating for the tour"""
        if 0 <= rating <= 5:
            self.ratings.append(rating)

    def get_average_rating(self) -> float:
        """Calculate average rating"""
        return sum(self.ratings) / len(self.ratings) if self.ratings else 0.0

    def to_dict(self) -> Dict:
        """Convert tour to dictionary"""
        return {
            'tour_id': self.tour_id,
            'title': self.title,
            'description': self.description,
            'landmark_type': self.landmark_type,
            'hotspots_count': len(self.hotspots),
            'audio_guides_count': len(self.audio_guides),
            'average_rating': self.get_average_rating()
        }


class VirtualTourManager:
