    def __init__(self, user_manager: UserManager):
        self.user_manager = user_manager
        self.tours: Dict[str, VirtualTour] = {}
        self.user_progress: Dict[str, Dict[str, List[str]]] = {}  # user_id -> {tour_id -> [completed_hotspots]}

    def create_tour(self, title: str, description: str, landmark_type: str) -> str:
        """Create a new virtual tour"""
        tour_id = str(uuid.uuid4())
        tour = VirtualTour(tour_id, title, description, landmark_type)
        self.tours[tour_id] = tour
        return tour_id

    def explore_tour(self, session_id: str, tour_id: str) -> Optional[Dict]:
        """User explores a virtual tour"""
        user = self.user_manager.get_user_by_session(session_id)
        tour = self.tours.get(tour_id)

        if not user or not tour:
