import asyncio
import json
import time
import uuid
from abc import ABC, abstractmethod
from collections import defaultdict, deque
from dataclasses import dataclass, field
from datetime import datetime
from enum import Enum
from typing import Dict, List, Optional, Set, Tuple, Any, Callable
from concurrent.futures import ThreadPoolExecutor
import re

# ==================== Core Data Models ====================

class NotebookVisibility(Enum):
    """Visibility settings for notebooks."""
    PUBLIC = "public"
    PRIVATE = "private"

class UserPermission(Enum):
    """Permission levels for notebook access."""
    READ = "read"
    WRITE = "write"
    OWNER = "owner"

@dataclass
class User:
    """Represents a user in the system."""
    id: str
    username: str
    email: str

@dataclass
class CodeSnippet:
    """Represents a code snippet with metadata."""
    id: str
    content: str
    language: str
    created_at: datetime
    updated_at: datetime
    created_by: str
    version: int = 1
    history: List[Dict] = field(default_factory=list)

    def to_dict(self) -> Dict:
        """Convert snippet to dictionary for serialization."""
        return {
            "id": self.id,
            "content": self.content,
            "language": self.language,
            "created_at": self.created_at.isoformat(),
            "updated_at": self.updated_at.isoformat(),
            "created_by": self.created_by,
            "version": self.version
        }

@dataclass
class Notebook:
    """Represents a collaborative notebook."""
    id: str
    name: str
    description: str
    visibility: NotebookVisibility
    owner_id: str
    created_at: datetime
    updated_at: datetime
    snippets: Dict[str, CodeSnippet] = field(default_factory=dict)
    notes: Dict[str, str] = field(default_factory=dict)
    collaborators: Dict[str, UserPermission] = field(default_factory=dict)

    def __post_init__(self):
        """Initialize with owner having owner permissions."""
        self.collaborators[self.owner_id] = UserPermission.OWNER

    def has_permission(self, user_id: str, required_permission: UserPermission) -> bool:
        """Check if user has required permission."""
        if user_id not in self.collaborators:
            return False

        user_perm = self.collaborators[user_id]

        # Permission hierarchy: READ < WRITE < OWNER
        permission_order = {
            UserPermission.READ: 1,
            UserPermission.WRITE: 2,
            UserPermission.OWNER: 3
