class CollaborationSession:
    """Manages a real-time collaboration session for a notebook."""

    def __init__(self, notebook_id: str):
        self.notebook_id = notebook_id
        self.active_users: Set[str] = set()
        self.cursor_positions: Dict[str, Dict] = {}  # user_id -> {snippet_id: position}
        self.lock = asyncio.Lock()
        self.change_callbacks: List[Callable] = []

    async def join(self, user_id: str):
        """User joins the collaboration session."""
        async with self.lock:
            self.active_users.add(user_id)
            await self._notify_change("user_joined", {"user_id": user_id})

    async def leave(self, user_id: str):
        """User leaves the collaboration session."""
        async with self.lock:
            self.active_users.discard(user_id)
            if user_id in self.cursor_positions:
                del self.cursor_positions[user_id]
            await self._notify_change("user_left", {"user_id": user_id})

    async def update_cursor(self, user_id: str, snippet_id: str, position: Dict):
        """Update user's cursor position in a snippet."""
        async with self.lock:
            if user_id not in self.cursor_positions:
                self.cursor_positions[user_id] = {}
            self.cursor_positions[user_id][snippet_id] = position
            await self._notify_change("cursor_updated", {
                "user_id": user_id,
                "snippet_id": snippet_id,
                "position": position
            })

    async def notify_change(self, change_type: str, data: Dict):
        """Notify about content changes."""
        async with self.lock:
            await self._notify_change(change_type, data)

    async def _notify_change(self, change_type: str, data: Dict):
        """Internal method to notify all callbacks."""
        for callback in self.change_callbacks:
            try:
                await callback(change_type, data)
            except Exception as e:
                print(f"Error in callback: {e}")

    def add_callback(self, callback: Callable):
        """Add a callback for change notifications."""
        self.change_callbacks.append(callback)

    def remove_callback(self, callback: Callable):
        """Remove a callback."""
        if callback in self.change_callbacks:
            self.change_callbacks.remove(callback)

