class VersionControlSystem:
    """Manages version control for notebook cells."""

    def __init__(self):
        self.history: Dict[str, VersionHistory] = {}
        self.locks: Dict[str, threading.Lock] = {}

    def track_cell(self, cell_id: str, initial_content: str, user_id: str):
        """Start tracking versions for a cell."""
        if cell_id not in self.history:
            self.history[cell_id] = VersionHistory(cell_id)
            self.locks[cell_id] = threading.Lock()

        with self.locks[cell_id]:
            self.history[cell_id].add_version(initial_content, user_id)

    def add_version(self, cell_id: str, content: str, user_id: str) -> int:
        """Add a new version and return version number."""
        if cell_id not in self.history:
            self.track_cell(cell_id, content, user_id)
            return 1

        with self.locks[cell_id]:
            return self.history[cell_id].add_version(content, user_id)

    def get_version(self, cell_id: str, version: int) -> Optional[str]:
        """Get content of a specific version."""
        if cell_id not in self.history:
            return None

        with self.locks[cell_id]:
            for v_num, content, _, _ in self.history[cell_id].versions:
                if v_num == version:
                    return content
        return None

    def get_history(self, cell_id: str) -> List[Tuple[int, datetime, str]]:
        """Get version history for a cell."""
        if cell_id not in self.history:
            return []

        with self.locks[cell_id]:
            return [(v_num, timestamp, user_id) 
                   for v_num, _, timestamp, user_id in self.history[cell_id].versions]

    def revert_to_version(self, cell_id: str, version: int, user_id: str) -> Optional[str]:
        """Revert cell to a specific version."""
        content = self.get_version(cell_id, version)
        if content:
            return self.add_version(cell_id, content, user_id)
        return None

