        Returns list of (cell_id, cell_type, relevance_score).
        """
        results = []
        query_lower = query.lower()

        for cell in notebook.cells:
            score = 0

            # Check if query is in content
            if query_lower in cell.content.lower():
                score += 10

            # Check for exact matches
            if query in cell.content:
                score += 5

            # Check in code cells for language-specific patterns
            if cell.cell_type == "code":
                # For code, also check if it's a function/class definition
                if cell.language == ProgrammingLanguage.PYTHON:
                    if re.search(rf'def\s+{query}', cell.content):
                        score += 20
                    if re.search(rf'class\s+{query}', cell.content):
                        score += 20
                elif cell.language == ProgrammingLanguage.JAVASCRIPT:
                    if re.search(rf'function\s+{query}', cell.content):
                        score += 20
                    if re.search(rf'class\s+{query}', cell.content):
                        score += 20

            if score > 0:
                results.append((cell.cell_id, cell.cell_type, score))

        # Sort by relevance score
        results.sort(key=lambda x: x[2], reverse=True)
        return results

