# Version Control System
# ============================================================================

@dataclass
class VersionHistory:
    """Tracks versions of a code snippet."""
    snippet_id: str
    versions: List[CodeSnippet] = field(default_factory=list)

    def add_version(self, snippet: CodeSnippet) -> None:
        """Add a new version to history."""
        self.versions.append(snippet)

    def get_version(self, version: int) -> Optional[CodeSnippet]:
        """Get specific version of snippet."""
        for snippet in self.versions:
            if snippet.version == version:
                return snippet
        return None

    def get_latest_version(self) -> Optional[CodeSnippet]:
        """Get latest version of snippet."""
        if not self.versions:
            return None
        return max(self.versions, key=lambda x: x.version)

class VersionControlSystem:
    """Manages version history for all snippets."""

    def __init__(self):
        self._history: Dict[str, VersionHistory] = {}
        self._lock = Lock()

    def track_snippet(self, snippet: CodeSnippet) -> None:
        """Start tracking a new snippet."""
        with self._lock:
            if snippet.id not in self._history:
                self._history[snippet.id] = VersionHistory(snippet_id=snippet.id)
            self._history[snippet.id].add_version(snippet)

    def update_snippet(self, snippet: CodeSnippet) -> None:
        """Update snippet and create new version."""
        with self._lock:
            if snippet.id in self._history:
                latest = self._history[snippet.id].get_latest_version()
                if latest and latest.content != snippet.content:
                    snippet.version = latest.version + 1
                self._history[snippet.id].add_version(snippet)

    def get_version(self, snippet_id: str, version: int) -> Optional[CodeSnippet]:
        """Get specific version of snippet."""
        with self._lock:
            if snippet_id in self._history:
                return self._history[snippet_id].get_version(version)
        return None

    def revert_to_version(self, snippet_id: str, version: int) -> Optional[CodeSnippet]:
        """Revert snippet to specific version."""
        with self._lock:
            if snippet_id in self._history:
                target_version = self._history[snippet_id].get_version(version)
                if target_version:
                    # Create a new version based on the old one
                    reverted = CodeSnippet(
                        id=snippet_id,
                        content=target_version.content,
                        language=target_version.language,
                        created_by=target_version.created_by,
                        created_at=target_version.created_at,
                        last_modified_by=f"reverted_by_{target_version.last_modified_by}",
                        last_modified_at=datetime.now(),
                        version=self._history[snippet_id].get_latest_version().version + 1
                    )
                    self._history[snippet_id].add_version(reverted)
                    return reverted
        return None

# ============================================================================
