class SyntaxHighlighter:
    """Provides syntax highlighting for different programming languages."""

    # Simple keyword highlighting rules for demonstration
    _KEYWORDS = {
        ProgrammingLanguage.PYTHON: {
            'keywords': ['def', 'class', 'if', 'else', 'elif', 'for', 'while', 
                        'import', 'from', 'as', 'return', 'try', 'except', 
                        'finally', 'with', 'as', 'lambda', 'yield', 'async', 'await'],
            'builtins': ['print', 'len', 'range', 'list', 'dict', 'str', 'int', 
                        'float', 'bool', 'True', 'False', 'None']
        },
        ProgrammingLanguage.JAVASCRIPT: {
            'keywords': ['function', 'class', 'if', 'else', 'for', 'while', 
                        'return', 'try', 'catch', 'finally', 'const', 'let', 'var',
                        'export', 'import', 'async', 'await'],
            'builtins': ['console', 'document', 'window', 'Array', 'Object', 
                        'String', 'Number', 'Boolean', 'Promise']
        },
        ProgrammingLanguage.JAVA: {
            'keywords': ['public', 'private', 'protected', 'class', 'interface',
                        'void', 'int', 'String', 'boolean', 'if', 'else', 'for',
                        'while', 'return', 'try', 'catch', 'finally', 'new'],
            'builtins': ['System', 'out', 'println', 'Math', 'Integer', 'Boolean']
        },
        ProgrammingLanguage.CPP: {
            'keywords': ['#include', 'using', 'namespace', 'std', 'int', 'void',
                        'class', 'public', 'private', 'if', 'else', 'for', 'while',
                        'return', 'try', 'catch', 'new', 'delete'],
            'builtins': ['cout', 'cin', 'endl', 'vector', 'string', 'map']
        }
    }

    @staticmethod
    def highlight(code: str, language: ProgrammingLanguage) -> str:
        """
        Apply syntax highlighting to code.
        Returns HTML with CSS classes for different token types.
        """
        if language == ProgrammingLanguage.PLAINTEXT:
            return f'<pre class="plaintext">{code}</pre>'

        rules = SyntaxHighlighter._KEYWORDS.get(language, {})
        keywords = rules.get('keywords', [])
        builtins = rules.get('builtins', [])

        # Simple tokenization for demonstration
        lines = code.split('\n')
        highlighted_lines = []

        for line in lines:
            tokens = line.split()
            highlighted_tokens = []

            for token in tokens:
                # Clean token for comparison
                clean_token = token.strip('.,;(){}[]"\':')

                if clean_token in keywords:
                    highlighted_tokens.append(f'<span class="keyword">{token}</span>')
                elif clean_token in builtins:
                    highlighted_tokens.append(f'<span class="builtin">{token}</span>')
                elif clean_token.isdigit():
                    highlighted_tokens.append(f'<span class="number">{token}</span>')
                elif token.startswith('"') and token.endswith('"'):
                    highlighted_tokens.append(f'<span class="string">{token}</span>')
                elif token.startswith("'") and token.endswith("'"):
                    highlighted_tokens.append(f'<span class="string">{token}</span>')
                elif token.startswith('//') or token.startswith('#'):
                    # Comment - highlight rest of line
                    highlighted_tokens.append(f'<span class="comment">{line[line.index(token):]}</span>')
                    break
                else:
                    highlighted_tokens.append(f'<span class="identifier">{token}</span>')

            highlighted_lines.append(' '.join(highlighted_tokens))

        return '<br>'.join(highlighted_lines)

# ============================================================================
# Code Completion
# ============================================================================

class CodeCompleter:
    """Provides code completion suggestions."""

    # Code snippets database for demonstration
    _SNIPPETS_DB = {
        ProgrammingLanguage.PYTHON: {
            'for loop': 'for item in collection:\n    # do something with item',
            'function': 'def function_name(parameters):\n    """Docstring"""\n    # function body\n    return value',
            'class': 'class ClassName:\n    def __init__(self, parameters):\n        self.parameters = parameters',
            'if statement': 'if condition:\n    # true branch\nelse:\n    # false branch'
        },
        ProgrammingLanguage.JAVASCRIPT: {
            'function': 'function functionName(parameters) {\n    // function body\n    return value;\n}',
            'arrow function': 'const functionName = (parameters) => {\n    // function body\n    return value;\n}',
            'class': 'class ClassName {\n    constructor(parameters) {\n        this.parameters = parameters;\n    }\n}'
        },
        ProgrammingLanguage.JAVA: {
            'main method': 'public static void main(String[] args) {\n    // code here\n}',
            'class': 'public class ClassName {\n    // fields and methods\n}',
            'for loop': 'for (int i = 0; i < length; i++) {\n    // loop body\n}'
        },
        ProgrammingLanguage.CPP: {
            'main function': 'int main() {\n    // code here\n    return 0;\n}',
            'class': 'class ClassName {\npublic:\n    // public members\nprivate:\n    // private members\n};',
            'for loop': 'for (int i = 0; i < length; i++) {\n    // loop body\n}'
        }
    }

    @staticmethod
    def get_completions(prefix: str, language: ProgrammingLanguage) -> List[str]:
        """
        Get code completion suggestions based on prefix.
        Returns list of matching keywords and snippets.
        """
        suggestions = []

        # Add language keywords
        if language in SyntaxHighlighter._KEYWORDS:
            keywords = SyntaxHighlighter._KEYWORDS[language]['keywords']
            suggestions.extend([kw for kw in keywords if kw.startswith(prefix)])

            builtins = SyntaxHighlighter._KEYWORDS[language]['builtins']
            suggestions.extend([b for b in builtins if b.startswith(prefix)])

        # Add snippet names
        if language in CodeCompleter._SNIPPETS_DB:
            snippet_names = CodeCompleter._SNIPPETS_DB[language].keys()
            suggestions.extend([name for name in snippet_names if prefix.lower() in name.lower()])

        return suggestions[:10]  # Limit to 10 suggestions

    @staticmethod
    def get_snippet(language: ProgrammingLanguage, snippet_name: str) -> Optional[str]:
        """Get a specific code snippet by name."""
        if language in CodeCompleter._SNIPPETS_DB:
            return CodeCompleter._SNIPPETS_DB[language].get(snippet_name)
        return None

# ============================================================================
# Real-time Collaboration Engine
# ============================================================================

class CollaborationSession:
    """Manages a real-time editing session for a notebook."""

    def __init__(self, notebook_id: str):
        self.notebook_id = notebook_id
        self.active_users: Set[str] = set()
        self.cursors: Dict[str, Dict] = {}  # user_id -> cursor position
        self.lock = Lock()
        self.last_activity = datetime.now()

    def join(self, user_id: str) -> None:
        """User joins the session."""
        with self.lock:
            self.active_users.add(user_id)
            self.cursors[user_id] = {"line": 0, "column": 0}
            self.last_activity = datetime.now()

    def leave(self, user_id: str) -> None:
        """User leaves the session."""
        with self.lock:
            self.active_users.discard(user_id)
            self.cursors.pop(user_id, None)
            self.last_activity = datetime.now()

    def update_cursor(self, user_id: str, line: int, column: int) -> None:
        """Update user's cursor position."""
        with self.lock:
            if user_id in self.cursors:
                self.cursors[user_id] = {"line": line, "column": column}
                self.last_activity = datetime.now()

    def get_active_users(self) -> List[str]:
        """Get list of active users."""
        with self.lock:
            return list(self.active_users)

class CollaborationEngine:
    """Manages real-time collaboration sessions."""

    def __init__(self):
        self.sessions: Dict[str, CollaborationSession] = {}
        self.lock = Lock()

    def get_or_create_session(self, notebook_id: str) -> CollaborationSession:
        """Get existing session or create new one."""
        with self.lock:
            if notebook_id not in self.sessions:
                self.sessions[notebook_id] = CollaborationSession(notebook_id)
            return self.sessions[notebook_id]

    def cleanup_inactive_sessions(self, timeout_seconds: int = 300) -> None:
        """Clean up sessions with no activity for timeout period."""
        with self.lock:
            current_time = datetime.now()
            inactive = []

            for notebook_id, session in self.sessions.items():
                time_diff = (current_time - session.last_activity).total_seconds()
                if time_diff > timeout_seconds and not session.active_users:
                    inactive.append(notebook_id)

            for notebook_id in inactive:
                del self.sessions[notebook_id]

