class SearchEngine:
    """Provides search functionality for notebooks."""

    @staticmethod
    def search_in_notebook(notebook: Notebook, query: str) -> List[Dict[str, Any]]:
        """
        Search for query in notebook.
        Returns list of matches with snippet info.
        """
        results = []
        query_lower = query.lower()

        for snippet in notebook.snippets:
            if query_lower in snippet.content.lower():
                results.append({
                    "snippet_id": snippet.id,
                    "content_preview": snippet.content[:100] + ("..." if len(snippet.content) > 100 else ""),
                    "language": snippet.language.value,
                    "created_by": snippet.created_by,
                    "version": snippet.version
                })

        return results

