        """Create user from dictionary"""
        return cls(**data)

@dataclass
class Comment:
    """Comment/note data model"""
    author: str
    content: str
    timestamp: datetime = field(default_factory=datetime.now)

    def to_dict(self) -> Dict:
        """Convert comment to dictionary"""
        return {
            'author': self.author,
