    comments: List[Comment] = field(default_factory=list)

    def to_dict(self) -> Dict:
        """Convert task to dictionary for serialization"""
        task_dict = asdict(self)
        task_dict['status'] = self.status.value
        task_dict['priority'] = self.priority.value
        task_dict['deadline'] = self.deadline.isoformat() if self.deadline else None
        task_dict['created_at'] = self.created_at.isoformat()
        task_dict['updated_at'] = self.updated_at.isoformat()
        task_dict['comments'] = [comment.to_dict() for comment in self.comments]
        return task_dict

    @classmethod
    def from_dict(cls, data: Dict) -> 'Task':
        """Create task from dictionary"""
        comments = [Comment.from_dict(c) for c in data.get('comments', [])]
        deadline = datetime.fromisoformat(data['deadline']) if data.get('deadline') else None
        created_at = datetime.fromisoformat(data['created_at']) if data.get('created_at') else datetime.now()
        updated_at = datetime.fromisoformat(data['updated_at']) if data.get('updated_at') else datetime.now()

        return cls(
