        self._write_json("notifications.json", notifications_data)

# ==================== NOTIFICATION SERVICE ====================

class NotificationService:
    """Service for handling notifications"""

    def __init__(self, storage: DataStorage):
        """Initialize notification service with storage"""
        self.storage = storage

    def notify_task_assigned(self, task: Task) -> None:
        """Create notification for task assignment"""
        notification_id = f"notif_{datetime.now().timestamp()}_{task.task_id}"
        message = f"You have been assigned a new task: {task.title} (Priority: {task.priority.value})"
        notification = Notification(
            notification_id=notification_id,
            user=task.assigned_to,
            message=message,
            notification_type="Task Assignment"
        )
        self.storage.save_notification(notification)

    def notify_deadline_approaching(self, task: Task) -> None:
        """Create notification for approaching deadline"""
        if not task.deadline:
            return

        # Check if deadline is within 24 hours
        time_until_deadline = task.deadline - datetime.now()
        if timedelta(hours=0) <= time_until_deadline <= timedelta(hours=24):
            notification_id = f"notif_{datetime.now().timestamp()}_{task.task_id}_deadline"
            message = f"Deadline approaching for task: {task.title}. Due: {task.deadline.strftime('%Y-%m-%d %H:%M')}"
            notification = Notification(
                notification_id=notification_id,
                user=task.assigned_to,
                message=message,
                notification_type="Deadline Alert"
            )
            self.storage.save_notification(notification)

    def notify_status_change(self, task: Task, old_status: TaskStatus) -> None:
        """Create notification for task status change"""
        notification_id = f"notif_{datetime.now().timestamp()}_{task.task_id}_status"
        message = f"Task '{task.title}' status changed from {old_status.value} to {task.status.value}"
        notification = Notification(
            notification_id=notification_id,
            user=task.created_by,
            message=message,
            notification_type="Status Update"
        )
        self.storage.save_notification(notification)

# ==================== REPORT SERVICE ====================

class ReportService:
    """Service for generating reports"""

    def __init__(self, storage: DataStorage):
        """Initialize report service with storage"""
        self.storage = storage

    def generate_completion_report(self) -> Dict:
        """Generate task completion rate report"""
        all_tasks = self.storage.get_all_tasks()
        if not all_tasks:
            return {"total": 0, "completed": 0, "rate": 0}

        completed_tasks = [t for t in all_tasks if t.status == TaskStatus.COMPLETED]
        completion_rate = (len(completed_tasks) / len(all_tasks)) * 100

        return {
            "total_tasks": len(all_tasks),
            "completed_tasks": len(completed_tasks),
            "completion_rate": round(completion_rate, 2)
        }

    def generate_overdue_report(self) -> Dict:
        """Generate overdue tasks report"""
        all_tasks = self.storage.get_all_tasks()
        now = datetime.now()

        overdue_tasks = []
        for task in all_tasks:
            if task.deadline and task.deadline < now and task.status != TaskStatus.COMPLETED:
                overdue_tasks.append({
                    "task_id": task.task_id,
                    "title": task.title,
                    "assigned_to": task.assigned_to,
                    "deadline": task.deadline.strftime('%Y-%m-%d %H:%M'),
                    "priority": task.priority.value
                })

        return {
            "total_overdue": len(overdue_tasks),
            "overdue_tasks": overdue_tasks
        }

    def generate_distribution_report(self) -> Dict:
        """Generate task distribution report among team members"""
        all_users = self.storage.get_all_users()
        all_tasks = self.storage.get_all_tasks()

        distribution = {}
        for user in all_users:
            user_tasks = [t for t in all_tasks if t.assigned_to == user.username]
            completed = [t for t in user_tasks if t.status == TaskStatus.COMPLETED]
            in_progress = [t for t in user_tasks if t.status == TaskStatus.IN_PROGRESS]
            pending = [t for t in user_tasks if t.status == TaskStatus.PENDING]

            distribution[user.username] = {
                "total": len(user_tasks),
                "completed": len(completed),
                "in_progress": len(in_progress),
                "pending": len(pending)
            }

        return distribution

