class StoryManager:
    def __init__(self):
        self.stories: Dict[str, Story] = {}
        self.locks: Dict[str, asyncio.Lock] = {}

    def create_story(self, title: str, creator_id: str) -> Story:
        story_id = str(uuid.uuid4())
        story = Story(
            id=story_id,
            title=title,
            creator_id=creator_id,
            created_at=datetime.now(),
            status=StoryStatus.DRAFT,
            collaborators={creator_id: UserRole.CREATOR}
        )
        self.stories[story_id] = story
        self.locks[story_id] = asyncio.Lock()
        return story

    async def edit_story(self, story_id: str, user_id: str, content: str, changes: List[str]) -> bool:
        if story_id not in self.stories:
            return False

        story = self.stories[story_id]
        if user_id not in story.collaborators:
            return False

        async with self.locks[story_id]:
            new_version = StoryVersion(
                version_id=story.current_version_id + 1,
                content=content,
                author_id=user_id,
                created_at=datetime.now(),
                changes=changes
            )
            story.versions.append(new_version)
            story.current_version_id += 1

            if story.status == StoryStatus.DRAFT:
                story.status = StoryStatus.IN_PROGRESS

            return True

    def get_story(self, story_id: str) -> Optional[Story]:
        return self.stories.get(story_id)

    def add_collaborator(self, story_id: str, user_id: str, role: UserRole) -> bool:
        if story_id not in self.stories:
            return False

