class ImageProcessor:
    """Handles all image processing operations."""

    @staticmethod
    def apply_brightness(image: Image.Image, factor: float) -> Image.Image:
        """Adjust image brightness."""
        enhancer = ImageEnhance.Brightness(image)
        return enhancer.enhance(factor)

    @staticmethod
    def apply_contrast(image: Image.Image, factor: float) -> Image.Image:
        """Adjust image contrast."""
        enhancer = ImageEnhance.Contrast(image)
        return enhancer.enhance(factor)

    @staticmethod
    def apply_saturation(image: Image.Image, factor: float) -> Image.Image:
        """Adjust image saturation."""
        enhancer = ImageEnhance.Color(image)
        return enhancer.enhance(factor)

    @staticmethod
    def apply_sharpness(image: Image.Image, factor: float) -> Image.Image:
        """Adjust image sharpness."""
        enhancer = ImageEnhance.Sharpness(image)
        return enhancer.enhance(factor)

    @staticmethod
    def apply_filter(image: Image.Image, filter_type: str) -> Image.Image:
        """Apply various filters to image."""
        filters = {
            'blur': ImageFilter.BLUR,
            'contour': ImageFilter.CONTOUR,
            'detail': ImageFilter.DETAIL,
            'edge_enhance': ImageFilter.EDGE_ENHANCE,
            'emboss': ImageFilter.EMBOSS,
            'smooth': ImageFilter.SMOOTH,
            'sharpen': ImageFilter.SHARPEN,
        }
        if filter_type in filters:
            return image.filter(filters[filter_type])
        return image

    @staticmethod
    def apply_color_correction(image: Image.Image, adjustments: Dict[str, float]) -> Image.Image:
        """Apply color correction adjustments."""
        # Convert to numpy array for advanced manipulation
        arr = np.array(image)

        # Apply RGB adjustments
        for i, channel in enumerate(['r', 'g', 'b']):
            if channel in adjustments:
                arr[:, :, i] = np.clip(arr[:, :, i] * adjustments[channel], 0, 255)

        return Image.fromarray(arr.astype('uint8'))

    @staticmethod
    def apply_frame(image: Image.Image, frame_data: str, thickness: int = 20) -> Image.Image:
        """Apply a frame to the image."""
        # Decode frame mask from base64
        frame_bytes = base64.b64decode(frame_data)
        frame_img = Image.open(io.BytesIO(frame_bytes)).convert("RGBA")

        # Resize frame to match image
        frame_img = frame_img.resize(image.size)

        # Composite image with frame
        result = Image.alpha_composite(image.convert("RGBA"), frame_img)
        return result.convert("RGB")

    @staticmethod
    def image_to_base64(image: Image.Image) -> str:
        """Convert PIL Image to base64 string."""
        buffered = io.BytesIO()
        image.save(buffered, format="PNG")
        return base64.b64encode(buffered.getvalue()).decode()

    @staticmethod
    def base64_to_image(data: str) -> Image.Image:
        """Convert base64 string to PIL Image."""
        image_data = base64.b64decode(data)
        return Image.open(io.BytesIO(image_data)).convert("RGB")

