class PhotoSession:
    """Represents a collaborative photo editing session."""

    def __init__(self, session_id: str, initial_image: Image.Image):
        self.session_id = session_id
        self.versions: List[PhotoVersion] = []
        self.comments: List[UserComment] = []
        self.custom_filters: Dict[str, CustomFilter] = {}
        self.custom_frames: Dict[str, CustomFrame] = {}
        self.current_image = initial_image
