        version = PhotoVersion(
            version_id=f"v{len(self.versions)}",
            timestamp=datetime.now(),
            image_data=ImageProcessor.image_to_base64(self.current_image),
            edit_history=self.edit_history.copy(),
            created_by=user_id
        )
