class ConnectionManager:
    """Manages WebSocket connections for real-time collaboration."""

    def __init__(self):
        self.active_connections: Dict[str, WebSocket] = {}
        self.user_rooms: Dict[str, str] = {}  # user_id -> room_id

    async def connect(self, websocket: WebSocket, user_id: str, room_id: str):
        await websocket.accept()
        self.active_connections[user_id] = websocket
        self.user_rooms[user_id] = room_id

    def disconnect(self, user_id: str):
        if user_id in self.active_connections:
            del self.active_connections[user_id]
        if user_id in self.user_rooms:
            del self.user_rooms[user_id]

    async def send_personal_message(self, message: dict, user_id: str):
        """Send message to a specific user."""
        if user_id in self.active_connections:
            await self.active_connections[user_id].send_json(message)

    async def broadcast_to_room(self, message: dict, room_id: str, exclude_user: str = None):
        """Broadcast message to all users in a room."""
        for user_id, ws in self.active_connections.items():
            if user_id != exclude_user and self.user_rooms.get(user_id) == room_id:
                try:
                    await ws.send_json(message)
                except:
                    pass

class PhotoSession:
    """Represents a collaborative photo editing session."""

    def __init__(self, session_id: str, initial_image: Image.Image):
        self.session_id = session_id
        self.versions: List[PhotoVersion] = []
        self.comments: List[UserComment] = []
        self.custom_filters: Dict[str, CustomFilter] = {}
        self.custom_frames: Dict[str, CustomFrame] = {}
        self.current_image = initial_image
        self.edit_history: List[EditOperation] = []

        # Create initial version
        self.create_version("system", "Initial version")

    def create_version(self, user_id: str, description: str = ""):
        """Create a new version snapshot."""
        version = PhotoVersion(
            version_id=f"v{len(self.versions)}",
            timestamp=datetime.now(),
            image_data=ImageProcessor.image_to_base64(self.current_image),
            edit_history=self.edit_history.copy(),
            created_by=user_id
        )
        self.versions.append(version)
        return version

    def revert_to_version(self, version_id: str) -> Optional[PhotoVersion]:
        """Revert to a previous version."""
        for version in self.versions:
            if version.version_id == version_id:
                self.current_image = ImageProcessor.base64_to_image(version.image_data)
                self.edit_history = version.edit_history.copy()
                return version
        return None

    def apply_edit(self, edit: EditOperation) -> Image.Image:
        """Apply an edit operation to the current image."""
        processor = ImageProcessor()

        if edit.tool == EditTool.BRIGHTNESS:
            factor = edit.parameters.get("factor", 1.0)
            self.current_image = processor.apply_brightness(self.current_image, factor)

        elif edit.tool == EditTool.CONTRAST:
            factor = edit.parameters.get("factor", 1.0)
            self.current_image = processor.apply_contrast(self.current_image, factor)

        elif edit.tool == EditTool.SATURATION:
            factor = edit.parameters.get("factor", 1.0)
            self.current_image = processor.apply_saturation(self.current_image, factor)

        elif edit.tool == EditTool.SHARPNESS:
            factor = edit.parameters.get("factor", 1.0)
            self.current_image = processor.apply_sharpness(self.current_image, factor)

        elif edit.tool == EditTool.FILTER:
            filter_type = edit.parameters.get("type", "blur")
            self.current_image = processor.apply_filter(self.current_image, filter_type)

        elif edit.tool == EditTool.COLOR_CORRECTION:
            adjustments = edit.parameters.get("adjustments", {})
            self.current_image = processor.apply_color_correction(self.current_image, adjustments)

        elif edit.tool == EditTool.FRAME:
            frame_id = edit.parameters.get("frame_id")
            if frame_id in self.custom_frames:
                frame_data = self.custom_frames[frame_id].frame_data
                thickness = edit.parameters.get("thickness", 20)
                self.current_image = processor.apply_frame(self.current_image, frame_data, thickness)

        self.edit_history.append(edit)
        return self.current_image

    def add_comment(self, comment: UserComment):
        """Add a comment to the session."""
        self.comments.append(comment)

    def resolve_comment(self, comment_id: str, user_id: str):
        """Mark a comment as resolved."""
        for comment in self.comments:
            if comment.comment_id == comment_id:
                comment.resolved = True
                break

    def add_custom_filter(self, filter_obj: CustomFilter):
        """Add a custom filter to the session."""
        self.custom_filters[filter_obj.filter_id] = filter_obj

    def add_custom_frame(self, frame_obj: CustomFrame):
        """Add a custom frame to the session."""
        self.custom_frames[frame_obj.frame_id] = frame_obj

    def get_session_state(self) -> dict:
        """Get current session state."""
        return {
            "session_id": self.session_id,
            "current_image": ImageProcessor.image_to_base64(self.current_image),
            "version_count": len(self.versions),
            "comment_count": len(self.comments),
            "active_users": [],  # Will be filled by manager
            "edit_history": [op.dict() for op in self.edit_history[-10:]],  # Last 10 edits
        }

