import json
from datetime import datetime
from typing import Dict, List, Optional, Any
from enum import Enum

class TaskType(Enum):
    PUZZLE = "puzzle"
    PHYSICAL = "physical"
    SCAVENGER = "scavenger"
    EDUCATIONAL = "educational"

class QuestStage:
    def __init__(self, stage_id: int, title: str, description: str, task_type: TaskType, task_data: Dict):
        self.stage_id = stage_id
        self.title = title
        self.description = description
        self.task_type = task_type
        self.task_data = task_data
        self.completed = False
        self.completion_time: Optional[datetime] = None

    def complete_stage(self):
        self.completed = True
        self.completion_time = datetime.now()

    def to_dict(self):
        return {
            "stage_id": self.stage_id,
            "title": self.title,
            "description": self.description,
            "task_type": self.task_type.value,
            "task_data": self.task_data,
            "completed": self.completed,
            "completion_time": self.completion_time.isoformat() if self.completion_time else None
        }

class Quest:
    def __init__(self, quest_id: str, title: str, description: str, created_by: str):
        self.quest_id = quest_id
        self.title = title
        self.description = description
        self.created_by = created_by
        self.created_date = datetime.now()
        self.stages: List[QuestStage] = []
        self.assigned_to: List[str] = []
        self.completed = False

    def add_stage(self, stage: QuestStage):
        self.stages.append(stage)

    def assign_to_family_member(self, member_name: str):
        if member_name not in self.assigned_to:
            self.assigned_to.append(member_name)

    def get_current_stage(self) -> Optional[QuestStage]:
        for stage in self.stages:
            if not stage.completed:
                return stage
        return None

    def complete_current_stage(self) -> bool:
        current_stage = self.get_current_stage()
        if current_stage:
            current_stage.complete_stage()

            if all(stage.completed for stage in self.stages):
                self.completed = True
            return True
        return False

    def get_progress(self) -> Dict:
        total_stages = len(self.stages)
        completed_stages = sum(1 for stage in self.stages if stage.completed)

        return {
            "completed": completed_stages,
            "total": total_stages,
            "percentage": (completed_stages / total_stages * 100) if total_stages > 0 else 0
        }

    def to_dict(self):
        return {
            "quest_id": self.quest_id,
            "title": self.title,
            "description": self.description,
            "created_by": self.created_by,
            "created_date": self.created_date.isoformat(),
            "stages": [stage.to_dict() for stage in self.stages],
            "assigned_to": self.assigned_to,
            "completed": self.completed,
            "progress": self.get_progress()
        }

