        if stage.task_type == TaskType.PUZZLE:
            return f"Brave adventurers! A challenging puzzle awaits: {stage.description}"
        elif stage.task_type == TaskType.PHYSICAL:
            return f"Time for action! Complete this physical challenge: {stage.description}"
