                    "visible": cell.visible or player_role == Role.PATHFINDER,
                    "has_player": cell.player_id is not None
                }
                if cell.player_id:
                    cell_data["player_id"] = cell.player_id
                row.append(cell_data)
            view.append(row)
        return view

    def is_path_clear(self, start: Tuple[int, int], end: Tuple[int, int], 
                     player_role: Role) -> bool:
        """Check if there's a clear path between two points using A* algorithm"""
        def heuristic(a, b):
            return abs(a[0] - b[0]) + abs(a[1] - b[1])

        open_set = []
        heapq.heappush(open_set, (0, start))
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, end)}

        while open_set:
            current = heapq.heappop(open_set)[1]

            if current == end:
                return True

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                neighbor = (current[0] + dr, current[1] + dc)

                if not (0 <= neighbor[0] < self.height and 0 <= neighbor[1] < self.width):
                    continue

                if not self.grid[neighbor[0]][neighbor[1]].is_traversable(player_role):
                    continue

                tentative_g_score = g_score[current] + 1

                if neighbor not in g_score or tentative_g_score < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g_score
                    f_score[neighbor] = tentative_g_score + heuristic(neighbor, end)
                    heapq.heappush(open_set, (f_score[neighbor], neighbor))

        return False

class GameState:
    """Manages the complete state of a game session"""

    def __init__(self, game_id: str, level: int = 1):
        self.game_id = game_id
        self.level = level
        self.maze = Maze(10 + level * 2, 10 + level * 2, level)
        self.players: Dict[str, Player] = {}
        self.current_turn = 0
        self.max_turns = 50 - level * 5
        self.game_active = True
        self.winner = False
        self.start_time = datetime.now()
        self.hints_given = 0
        self.collaboration_score = 0

        # Place players at start
        self._place_players_at_start()

    def _place_players_at_start(self):
        """Place all players at the maze start position"""
        start_positions = [
            (self.maze.start_pos[0], self.maze.start_pos[1]),
            (self.maze.start_pos[0], self.maze.start_pos[1] + 1),
            (self.maze.start_pos[0] + 1, self.maze.start_pos[1]),
            (self.maze.start_pos[0] + 1, self.maze.start_pos[1] + 1)
        ]

        for i, (player_id, player) in enumerate(self.players.items()):
            if i < len(start_positions):
                pos = start_positions[i]
                player.position = pos
                self.maze.grid[pos[0]][pos[1]].player_id = player_id

    def add_player(self, player_id: str, username: str, role: Role):
        """Add a player to the game with a specific role"""
        if len(self.players) >= 4:
            raise ValueError("Maximum 4 players allowed")

        start_pos = self.maze.start_pos
        player = Player(
            player_id=player_id,
            username=username,
            role=role,
            position=start_pos,
            actions_remaining=3
        )
        self.players[player_id] = player

        # Find empty starting cell
        for dr, dc in [(0, 0), (0, 1), (1, 0), (1, 1)]:
            r, c = start_pos[0] + dr, start_pos[1] + dc
            if (0 <= r < self.maze.height and 0 <= c < self.maze.width and
                self.maze.grid[r][c].player_id is None):
                player.position = (r, c)
                self.maze.grid[r][c].player_id = player_id
                break

    def perform_action(self, player_id: str, action_type: ActionType, 
                      data: Dict) -> Dict:
        """Perform an action for a player and return result"""
        if not self.game_active:
            return {"success": False, "message": "Game is not active"}

        player = self.players.get(player_id)
        if not player:
            return {"success": False, "message": "Player not found"}

        if not player.has_action_this_turn:
            return {"success": False, "message": "No actions remaining this turn"}

        if not player.can_perform_action(action_type):
            return {"success": False, "message": f"Role {player.role.value} cannot perform {action_type.value}"}

        result = {"success": False, "message": "", "points": 0}

        if action_type == ActionType.MOVE:
            result = self._move_player(player, data.get("direction"))
        elif action_type == ActionType.PLACE_BLOCK:
            result = self._place_block(player, data.get("position"))
        elif action_type == ActionType.REMOVE_BLOCK:
            result = self._remove_block(player, data.get("block_id"))
        elif action_type == ActionType.REVEAL_PATH:
            result = self._reveal_path(player, data.get("position"))
        elif action_type == ActionType.SWAP_BLOCKS:
            result = self._swap_blocks(player, data.get("block_id1"), data.get("block_id2"))
        elif action_type == ActionType.BUILD_BRIDGE:
            result = self._build_bridge(player, data.get("position"))
        elif action_type == ActionType.USE_HINT:
            result = self._use_hint(player)

        if result["success"]:
            player.actions_remaining -= 1
            player.points += result.get("points", 0)
            player.has_action_this_turn = player.actions_remaining > 0

            # Check if all players have used their actions
            if all(not p.has_action_this_turn for p in self.players.values()):
                self._end_turn()

        return result

    def _move_player(self, player: Player, direction_str: str) -> Dict:
        """Move player in specified direction"""
        try:
            direction = Direction[direction_str.upper()]
        except KeyError:
            return {"success": False, "message": "Invalid direction"}

        new_r = player.position[0] + direction.value[0]
        new_c = player.position[1] + direction.value[1]

        # Check bounds
        if not (0 <= new_r < self.maze.height and 0 <= new_c < self.maze.width):
            return {"success": False, "message": "Cannot move outside maze"}

        target_cell = self.maze.grid[new_r][new_c]

        # Check if cell is traversable
        if not target_cell.is_traversable(player.role):
            return {"success": False, "message": "Cannot move into this cell"}

        # Check if cell is occupied by another player
        if target_cell.player_id is not None:
            return {"success": False, "message": "Cell occupied by another player"}

        # Move player
        old_r, old_c = player.position
        self.maze.grid[old_r][old_c].player_id = None
        self.maze.grid[new_r][new_c].player_id = player.player_id
        player.position = (new_r, new_c)

        # Check if player reached goal
        if (new_r, new_c) == self.maze.goal_pos:
            return {
                "success": True, 
                "message": f"Player {player.username} reached the goal!",
                "points": 100 * self.level,
                "reached_goal": True
            }

        return {
            "success": True, 
            "message": f"Moved {direction_str}",
            "points": 10
        }

    def _place_block(self, player: Player, position: Tuple[int, int]) -> Dict:
        """Place a blocking obstacle"""
        if not position:
            return {"success": False, "message": "No position specified"}

        r, c = position
        cell = self.maze.grid[r][c]

        if cell.cell_type != CellType.PATH:
            return {"success": False, "message": "Can only place blocks on paths"}

        if cell.player_id is not None:
            return {"success": False, "message"}

