"""
ImageCanvasComposer - Graphics application for creating and managing multiple canvas layers,
applying graphical effects, and exporting composite images.
"""

import numpy as np
from PIL import Image, ImageFilter, ImageOps
import tkinter as tk
from tkinter import filedialog, messagebox, ttk
import os
from dataclasses import dataclass, field
from typing import List, Optional, Tuple
import json


# ==================== LAYER MANAGEMENT SYSTEM ====================

@dataclass
class CanvasLayer:
    """Represents an individual image layer in the canvas."""
    id: str
    name: str
    image: Image.Image
    position: Tuple[int, int] = (0, 0)
    opacity: float = 1.0
    visible: bool = True
    effects: List[str] = field(default_factory=list)
    blend_mode: str = "normal"

    def get_processed_image(self) -> Image.Image:
        """Return the image with applied effects."""
        processed = self.image.copy()

        # Apply alpha for opacity
        if self.opacity < 1.0:
            alpha = processed.split()[3] if processed.mode == 'RGBA' else Image.new('L', processed.size, 255)
            alpha = alpha.point(lambda p: p * self.opacity)
            if processed.mode != 'RGBA':
                processed = processed.convert('RGBA')
            processed.putalpha(alpha)

        return processed


class LayerManager:
    """Manages multiple canvas layers with ordering and operations."""

    def __init__(self):
        self.layers: List[CanvasLayer] = []
        self.active_layer_index: Optional[int] = None

    def add_layer(self, image: Image.Image, name: str = "New Layer") -> str:
        """Add a new layer to the canvas."""
        layer_id = str(len(self.layers))
        layer = CanvasLayer(id=layer_id, name=name, image=image)
        self.layers.append(layer)
        self.active_layer_index = len(self.layers) - 1
        return layer_id

    def remove_layer(self, layer_id: str) -> bool:
        """Remove a layer by ID."""
        for i, layer in enumerate(self.layers):
            if layer.id == layer_id:
                self.layers.pop(i)
                if self.active_layer_index == i:
                    self.active_layer_index = None if not self.layers else max(0, i-1)
                return True
        return False

    def reorder_layer(self, layer_id: str, new_index: int) -> bool:
        """Move a layer to a new position in the stack."""
        for i, layer in enumerate(self.layers):
            if layer.id == layer_id:
                layer_to_move = self.layers.pop(i)
                self.layers.insert(new_index, layer_to_move)
                # Update active layer index
                if self.active_layer_index == i:
                    self.active_layer_index = new_index
                elif self.active_layer_index > i and self.active_layer_index <= new_index:
                    self.active_layer_index -= 1
                elif self.active_layer_index < i and self.active_layer_index >= new_index:
                    self.active_layer_index += 1
                return True
        return False

    def get_layer(self, layer_id: str) -> Optional[CanvasLayer]:
        """Get a layer by ID."""
        for layer in self.layers:
            if layer.id == layer_id:
                return layer
        return None

    def get_active_layer(self) -> Optional[CanvasLayer]:
        """Get the currently active layer."""
        if self.active_layer_index is not None and 0 <= self.active_layer_index < len(self.layers):
            return self.layers[self.active_layer_index]
        return None

    def set_active_layer(self, layer_id: str) -> bool:
        """Set a layer as active by ID."""
        for i, layer in enumerate(self.layers):
            if layer.id == layer_id:
                self.active_layer_index = i
                return True
        return False


# ==================== GRAPHICAL EFFECTS AND FILTERS ====================

class GraphicsEffects:
    """Provides various graphical effects and filters for images."""

    @staticmethod
    def adjust_brightness_contrast(image: Image.Image, brightness: float = 1.0, contrast: float = 1.0) -> Image.Image:
        """Adjust brightness and contrast of an image."""
        if brightness == 1.0 and contrast == 1.0:
            return image.copy()

        # Convert to numpy array for processing
        arr = np.array(image, dtype=np.float32)

        # Apply brightness
        arr *= brightness

        # Apply contrast
        mean = arr.mean()
        arr = mean + contrast * (arr - mean)

        # Clip values to valid range
        arr = np.clip(arr, 0, 255)

        return Image.fromarray(arr.astype(np.uint8))

    @staticmethod
    def apply_blur(image: Image.Image, radius: int = 2) -> Image.Image:
        """Apply Gaussian blur to an image."""
        return image.filter(ImageFilter.GaussianBlur(radius))

    @staticmethod
    def apply_sharpen(image: Image.Image) -> Image.Image:
        """Apply sharpening filter to an image."""
        return image.filter(ImageFilter.SHARPEN)

    @staticmethod
    def adjust_color_balance(image: Image.Image, 
                            red_scale: float = 1.0, 
                            green_scale: float = 1.0, 
                            blue_scale: float = 1.0) -> Image.Image:
        """Adjust color balance of an image."""
        if red_scale == 1.0 and green_scale == 1.0 and blue_scale == 1.0:
            return image.copy()

        arr = np.array(image, dtype=np.float32)

        # Apply color scaling
        arr[..., 0] *= red_scale    # Red channel
        if arr.shape[2] > 1:
            arr[..., 1] *= green_scale  # Green channel
        if arr.shape[2] > 2:
            arr[..., 2] *= blue_scale   # Blue channel

        arr = np.clip(arr, 0, 255)
        return Image.fromarray(arr.astype(np.uint8))

    @staticmethod
    def convert_to_grayscale(image: Image.Image) -> Image.Image:
        """Convert image to grayscale."""
        return ImageOps.grayscale(image).convert('RGB')

    @staticmethod
    def apply_edge_detection(image: Image.Image) -> Image.Image:
        """Apply edge detection filter."""
        return image.filter(ImageFilter.FIND_EDGES)


